#Python Function for the lambda 'dlh_s3_event_planner_know' update everytime a query changes

def build_athena_query(credit_union_q: str, query_name: str, temp_path: str) -> str:
    query_member_key_trends = f"UNLOAD (SELECT fi.idfi AS idfi, m.member_id, m.member_number, CASE WHEN m.member_number > 0 THEN 'Valid' ELSE 'Invalid' END AS member_number_is_valid, CASE WHEN m.inactive_flag = 'I' THEN 'Inactive Flag' ELSE 'Active Flag' END AS member_inactive_flag_status, CASE WHEN m.all_accounts_closed = 1 THEN 'All Closed' WHEN m.all_accounts_closed = 0 THEN 'Has Open Accounts' ELSE 'Unknown/NULL' END AS member_accounts_status, CASE WHEN m.member_number IS NOT NULL AND m.all_accounts_closed = 0 AND m.inactive_flag <> 'I' THEN 'Active' ELSE 'Inactive' END AS member_status, m.inactive_flag AS member_inactive_flag_code, m.all_accounts_closed AS member_all_accounts_closed_flag, CAST(m.join_date AS DATE) AS join_date, m.all_accounts_closed AS closed_membership, m.modified_timestamp, AVG(a.current_balance) AS average_balance, SUM(a.current_balance) AS total_balance, SUM(CASE WHEN a.discriminator IN ('S','D','C') THEN a.current_balance ELSE 0 END) AS total_deposits_balance, SUM(CASE WHEN a.discriminator = 'L' THEN a.current_balance ELSE 0 END) AS total_loans_balance FROM \"AwsDataCatalog\".\"silver_know\".\"member\" m LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"account\" a ON m.member_id = a.member_number AND m.credit_union = a.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(trim(fi.prodigy_code)) = '{credit_union_q}' WHERE m.credit_union = '{credit_union_q}' AND a.credit_union = '{credit_union_q}' GROUP BY fi.idfi, m.member_id, m.member_number, m.join_date, m.inactive_flag, m.all_accounts_closed, m.modified_timestamp ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_accounts_general = f"UNLOAD (WITH member_account_stats AS ( SELECT credit_union, member_number, COUNT(*) AS total_accounts_per_member, COUNT(CASE WHEN date_closed IS NOT NULL THEN 1 END) AS deleted_accounts_per_member, COUNT( CASE WHEN last_activity < date_add('day', -90, current_date) OR last_activity IS NULL THEN 1 END ) AS inactive_accounts_per_member, CASE WHEN COUNT(*) > 1 THEN 'True' ELSE 'False' END AS has_multiple_accounts FROM\"AwsDataCatalog\".\"silver_know\".\"account\" WHERE credit_union = '{credit_union_q}' AND member_number > 0 AND UPPER((discriminator)) IN ('S','D','C','U') GROUP BY credit_union, member_number ), cu_info AS ( SELECT DISTINCT credit_union, credit_union_name FROM\"AwsDataCatalog\".\"silver_know\".\"credit_union_info\" WHERE credit_union = '{credit_union_q}' ), th_recent AS ( SELECT DISTINCT credit_union, account_id FROM\"AwsDataCatalog\".\"silver_know\".\"transaction_history\" WHERE credit_union = '{credit_union_q}' AND date_actual >= date_add('day', -90, current_date) AND void_flag = 0 ) SELECT fi.idfi AS idfi, a.account_id, a.member_number AS member_id, ci.credit_union_name AS cu_name, CASE WHEN ma.member_number IS NOT NULL THEN 'Online Application' WHEN (a.created_by_userid) IN ('88','87','92','95','XXZ') THEN 'Automated Process' WHEN regexp_like((a.created_by_userid), '^[0-9]+$') THEN 'Staff-Assisted' WHEN (a.created_by_userid) = 'PCN' THEN 'Migration' ELSE 'Unknown' END AS estimated_channel, CASE WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'PSAV' THEN 'Savings' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'SSAV' THEN 'Savings' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'MMA' THEN 'Money Market' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'CCO' THEN 'Share Certificate' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'CLUB' THEN 'Club Savings' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'HYS' THEN 'High Yield Savings' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'YSAV' THEN 'Youth Savings' WHEN UPPER((a.discriminator)) = 'S' AND UPPER((a.account_type)) = 'SCO' THEN 'Share Certificate' WHEN UPPER((a.discriminator)) = 'S' THEN 'Other Savings' WHEN UPPER((a.discriminator)) = 'D' AND UPPER((a.account_type)) = 'CHK' THEN 'Checking' WHEN UPPER((a.discriminator)) = 'D' THEN 'Other Checking' WHEN UPPER((a.discriminator)) = 'C' AND UPPER((a.account_type)) = 'CERT' THEN 'Certificate' WHEN UPPER((a.discriminator)) = 'C' AND UPPER((a.account_type)) = 'TICD' THEN 'Term Certificate' WHEN UPPER((a.discriminator)) = 'C' AND UPPER((a.account_type)) = 'RICD' THEN 'IRA Certificate' WHEN UPPER((a.discriminator)) = 'C' THEN 'Other Certificate' WHEN UPPER((a.discriminator)) = 'U' THEN 'Special Account' ELSE concat(CAST(a.discriminator AS varchar), '-', CAST(a.account_type AS varchar)) END AS account_type_description, CASE WHEN UPPER((a.discriminator)) = 'S' THEN 'SAVINGS' WHEN UPPER((a.discriminator)) = 'D' THEN 'CHECKING' WHEN UPPER((a.discriminator)) = 'C' THEN 'CERTIFICATES' WHEN UPPER((a.discriminator)) = 'U' THEN 'SPECIAL' ELSE 'OTHER' END AS main_account_category, a.date_opened AS created_date, a.date_closed AS deleted_date, CASE WHEN a.date_closed IS NOT NULL THEN 'Deleted' WHEN UPPER((COALESCE(a.access_control, ''))) IN ('B','R') THEN 'Blocked' ELSE 'Enabled' END AS deleted_status, CASE WHEN th.account_id IS NOT NULL THEN 'Active' ELSE 'Inactive' END AS active_status_last_3_months, a.account_number, a.current_balance, mas.total_accounts_per_member AS number_of_accounts_per_member, mas.has_multiple_accounts, mas.deleted_accounts_per_member AS accounts_deleted_per_member, mas.inactive_accounts_per_member AS accounts_inactive_per_member FROM\"AwsDataCatalog\".\"silver_know\".\"account\" a LEFT JOIN cu_info ci ON ci.credit_union = '{credit_union_q}' LEFT JOIN member_account_stats mas ON mas.member_number = a.member_number LEFT JOIN\"AwsDataCatalog\".\"silver_know\".\"member_application\" ma ON ma.credit_union = '{credit_union_q}' AND ma.member_number = a.member_number LEFT JOIN th_recent th on th.account_id = a.account_id LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = a.credit_union WHERE a.credit_union = '{credit_union_q}' AND a.member_number > 0 AND UPPER((a.discriminator)) IN ('S','D','C','U') ORDER BY a.member_number, CASE WHEN UPPER((a.discriminator)) = 'S' THEN 1 WHEN UPPER((a.discriminator)) = 'D' THEN 2 WHEN UPPER((a.discriminator)) = 'C' THEN 3 WHEN UPPER((a.discriminator)) = 'U' THEN 4 ELSE 5 END, a.date_opened DESC ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_accounts_transactions = f"UNLOAD (WITH tx_monthly AS ( SELECT th.credit_union, th.account_id, CAST(date_trunc('month', CAST(th.date_effective AS date)) AS date) AS month_start, COUNT(DISTINCT th.transaction_history_id) AS Transactions, COUNT(DISTINCT CASE WHEN th.total_amount > 0 THEN th.transaction_history_id END) AS Deposits, COUNT(DISTINCT CASE WHEN th.total_amount < 0 THEN th.transaction_history_id END) AS Withdrawals, ROUND(SUM(CASE WHEN th.total_amount > 0 THEN th.total_amount ELSE 0 END), 2) AS total_credits, ROUND(SUM(CASE WHEN th.total_amount < 0 THEN ABS(th.total_amount) ELSE 0 END), 2) AS total_debits, ROUND(SUM(th.total_amount), 2) AS net_change_for_month FROM \"AwsDataCatalog\".\"silver_know\".\"transaction_history\" th WHERE th.credit_union = '{credit_union_q}' AND th.void_flag = 0 AND CAST(th.date_effective AS date) >= date_add('month', -12, current_date) GROUP BY th.credit_union, th.account_id, CAST(date_trunc('month', CAST(th.date_effective AS date)) AS date) ), tx_with_suffix AS ( SELECT t.*, SUM(t.net_change_for_month) OVER ( PARTITION BY t.credit_union, t.account_id ORDER BY t.month_start ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ) AS net_change_from_this_month_forward FROM tx_monthly t ) SELECT fi.idfi AS idfi, date_format(CAST(t.month_start AS timestamp), '%Y-%m') AS month_year, a.account_number, a.member_number, CASE UPPER((a.discriminator)) WHEN 'S' THEN 'SAVINGS' WHEN 'D' THEN 'CHECKING' WHEN 'C' THEN 'CERTIFICATES' WHEN 'L' THEN 'LOANS' WHEN 'U' THEN 'SPECIAL' ELSE 'OTHER' END AS account_category, a.account_type, a.current_balance, t.Transactions, t.Deposits, t.Withdrawals, t.total_credits, t.total_debits, t.net_change_for_month, ROUND(a.current_balance - COALESCE(t.net_change_from_this_month_forward, 0), 2) AS approximate_beginning_balance, CASE WHEN t.Transactions > 0 THEN 'Active' ELSE 'Inactive' END AS activity_status FROM tx_with_suffix t JOIN \"AwsDataCatalog\".\"silver_know\".\"account\" a ON a.account_id = t.account_id LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = '{credit_union_q}' WHERE a.credit_union = '{credit_union_q}' AND a.member_number > 0 AND UPPER((a.discriminator)) IN ('S','D','C','U') ORDER BY month_year DESC, account_category, a.account_number ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_cards_general = f"UNLOAD (WITH all_physical_cards AS ( SELECT ecf.credit_union AS credit_union, ecf.member_number AS member_id, CAST(ecf.record_number AS varchar) AS card_id, CAST(substr(CAST(ecf.record_number AS varchar), greatest(length(CAST(ecf.record_number AS varchar)) - 3, 1), 4) AS varchar) AS last_4_digits, CAST(CASE WHEN x.credit_card = 'Y' THEN CONCAT(x.description, ' Credit Card') WHEN x.debit_card = 'Y' THEN x.description WHEN x.atm_card = 'Y' THEN x.description ELSE COALESCE(x.description, 'Unknown Card') END AS varchar) AS card_type, CAST(COALESCE(x.card_issuer, 'Unknown') AS varchar) AS card_brand, ecf.issue_date AS creation_date, ecf.block_date AS deleted_date, ecf.expire_date AS expiration_date, CASE WHEN x.credit_card = 'Y' THEN CAST(0 AS decimal(15,2)) ELSE COALESCE(ecf.share_acct_bal, ecf.draft_acct_bal, 0) END AS balance_or_credit_limit, CAST(CASE WHEN x.credit_card = 'Y' THEN 0 ELSE NULL END AS decimal(15,2)) AS credit_used, CAST(CASE WHEN x.credit_card = 'Y' THEN 0 ELSE NULL END AS decimal(15,2)) AS credit_used_percentage, CAST(CASE WHEN ecf.block_date IS NOT NULL THEN 'Blocked' WHEN TRIM(CAST(ecf.reject_code AS varchar)) IN ('34','43') THEN 'Fraud Block' WHEN TRIM(CAST(ecf.reject_code AS varchar)) IN ('36','41') THEN 'Lost/Stolen Block' WHEN TRIM(CAST(ecf.reject_code AS varchar)) = '07' THEN 'Special Handling' WHEN ecf.expire_date < current_date THEN 'Expired' WHEN ecf.last_pin_used_date IS NOT NULL THEN 'Active' WHEN ecf.issue_date IS NOT NULL THEN 'Issued Not Used' ELSE 'Unknown' END AS varchar) AS status, CAST('N/A' AS varchar) AS delinquency_bracket, ecf.last_pin_used_date AS activation_date, CAST(CASE WHEN ecf.last_pin_used_date IS NOT NULL THEN 'True' ELSE 'False' END AS varchar) AS is_activated, CAST(CASE WHEN TRIM(CAST(ecf.reject_code AS varchar)) IN ('34','43') THEN 'True' WHEN TRIM(COALESCE(CAST(ecf.lost_or_stolen AS varchar), '')) <> '' THEN 'True' ELSE 'False' END AS varchar) AS fraud_incident, ecf.last_pin_used_date AS last_activity_date, CAST(CASE WHEN x.credit_card = 'Y' THEN 'Physical Credit' WHEN x.debit_card = 'Y' THEN 'Physical Debit' WHEN x.atm_card = 'Y' THEN 'Physical ATM' ELSE 'Physical Other' END AS varchar) AS card_source, ecf.card_type AS raw_card_type FROM \"AwsDataCatalog\".\"silver_know\".\"eft_card_file\" ecf LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"pd_xmaif\" x ON ecf.card_type = x.card_type WHERE ecf.credit_union = '{credit_union_q}' AND x.credit_union = '{credit_union_q}' AND x.inactive_flag = 0 ), credit_card_accounts AS ( SELECT a.credit_union AS credit_union, a.member_number AS member_id, CAST(al.account_id AS varchar) AS card_id, CAST('****' AS varchar) AS last_4_digits, CAST('Credit Account' AS varchar) AS card_type, CAST('Unknown' AS varchar) AS card_brand, COALESCE(al.funded_date, a.date_opened) AS creation_date, a.date_closed AS deleted_date, al.credit_expiration AS expiration_date, al.credit_limit AS balance_or_credit_limit, a.current_balance AS credit_used, CASE WHEN al.credit_limit > 0 THEN ROUND((a.current_balance * 100.0) / al.credit_limit, 2) ELSE 0 END AS credit_used_percentage, CAST(CASE WHEN a.date_closed IS NOT NULL THEN 'Closed' WHEN a.charge_off_date IS NOT NULL THEN 'Charged Off' WHEN al.next_payment_date IS NOT NULL AND date_diff('day', al.next_payment_date, current_date) > 30 THEN 'Delinquent' WHEN a.current_balance > al.credit_limit THEN 'Over Limit' WHEN UPPER(TRIM(a.status)) = 'ACTIVE' THEN 'Active' WHEN UPPER(TRIM(a.status)) = 'CLOSED' THEN 'Closed' WHEN UPPER(TRIM(a.status)) = 'FROZEN' THEN 'Frozen' ELSE 'Active' END AS varchar) AS status, CAST(CASE WHEN al.next_payment_date IS NULL THEN 'Unknown' WHEN date_diff('day', al.next_payment_date, current_date) <= 0 THEN 'Current' WHEN date_diff('day', al.next_payment_date, current_date) BETWEEN 1 AND 30 THEN '1-30 Days' WHEN date_diff('day', al.next_payment_date, current_date) BETWEEN 31 AND 60 THEN '31-60 Days' WHEN date_diff('day', al.next_payment_date, current_date) BETWEEN 61 AND 90 THEN '61-90 Days' WHEN date_diff('day', al.next_payment_date, current_date) BETWEEN 91 AND 120 THEN '91-120 Days' WHEN date_diff('day', al.next_payment_date, current_date) > 120 THEN '120+ Days' ELSE 'Current' END AS varchar) AS delinquency_bracket, COALESCE(al.funded_date, a.date_opened) AS activation_date, CAST(CASE WHEN COALESCE(al.funded_date, a.date_opened) IS NOT NULL THEN 'True' ELSE 'False' END AS varchar) AS is_activated, CAST(CASE WHEN a.charge_off_date IS NOT NULL THEN 'True' WHEN UPPER(TRIM(a.status)) = 'FRAUD' THEN 'True' ELSE 'False' END AS varchar) AS fraud_incident, al.last_payment_date AS last_activity_date, CAST('Credit Account' AS varchar) AS card_source FROM \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al INNER JOIN \"AwsDataCatalog\".\"silver_know\".\"account\" a ON al.account_id = a.account_id AND al.credit_union = a.credit_union WHERE a.credit_union = '{credit_union_q}' AND al.credit_union = '{credit_union_q}' AND al.credit_limit > 0 AND UPPER(TRIM(a.discriminator)) = 'L' AND a.member_number > 0 ), member_card_types AS ( SELECT credit_union, member_id, CASE WHEN COUNT(CASE WHEN card_source IN ('Physical Debit','Physical ATM') THEN 1 END) > 0 AND COUNT(CASE WHEN card_source IN ('Physical Credit','Credit Account') THEN 1 END) > 0 THEN 'Both' WHEN COUNT(CASE WHEN card_source IN ('Physical Debit','Physical ATM') THEN 1 END) > 0 THEN 'Debit Only' WHEN COUNT(CASE WHEN card_source IN ('Physical Credit','Credit Account') THEN 1 END) > 0 THEN 'Credit Only' ELSE 'Unknown' END AS member_card_portfolio FROM ( SELECT credit_union, member_id, card_source FROM all_physical_cards UNION ALL SELECT credit_union, member_id, card_source FROM credit_card_accounts ) all_cards GROUP BY credit_union, member_id ) SELECT fi.idfi AS idfi, uc.member_id, uc.card_id, uc.last_4_digits, uc.card_type, uc.card_brand, uc.creation_date, uc.deleted_date, uc.expiration_date, uc.balance_or_credit_limit, uc.credit_used, uc.credit_used_percentage, uc.status, uc.delinquency_bracket, uc.activation_date, uc.is_activated, CASE WHEN uc.last_activity_date IS NULL THEN 'True' WHEN date_diff('day', uc.last_activity_date, current_date) > 90 THEN 'True' ELSE 'False' END AS inactivity_flag, uc.fraud_incident, uc.card_source, mct.member_card_portfolio FROM ( SELECT credit_union, member_id, card_id, last_4_digits, card_type, card_brand, creation_date, deleted_date, expiration_date, balance_or_credit_limit, credit_used, CAST(credit_used_percentage AS decimal(15,2)) AS credit_used_percentage, status, delinquency_bracket, activation_date, is_activated, fraud_incident, last_activity_date, card_source, raw_card_type FROM all_physical_cards UNION ALL SELECT credit_union, member_id, card_id, last_4_digits, card_type, card_brand, creation_date, deleted_date, expiration_date, balance_or_credit_limit, credit_used, CAST(credit_used_percentage AS decimal(15,2)) AS credit_used_percentage, status, delinquency_bracket, activation_date, is_activated, fraud_incident, last_activity_date, card_source, CAST(NULL AS varchar) AS raw_card_type FROM credit_card_accounts ) uc LEFT JOIN member_card_types mct ON uc.credit_union = mct.credit_union AND uc.member_id = mct.member_id LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = uc.credit_union ORDER BY uc.credit_union, uc.member_id, uc.card_source, uc.card_type, uc.creation_date DESC ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_cards_transactions = f"UNLOAD (WITH filtered_th AS ( SELECT th.credit_union, th.transaction_history_id, th.account_id, th.member_id, th.date_actual, th.total_amount, substr(upper((th.tran_code)), 1, 4) AS tran_prefix, date_format(CAST(th.date_actual AS timestamp), '%Y-%m') AS period FROM\"AwsDataCatalog\".\"silver_know\".\"transaction_history\" th WHERE th.credit_union = '{credit_union_q}' AND th.date_actual >= DATE '2025-01-01' AND ( th.tran_code LIKE 'DRWD%' OR th.tran_code LIKE 'TLT%' ) ), member_card_types AS ( SELECT ec.credit_union, ec.member_number, CASE WHEN count_if(upper((ec.card_type)) = 'D') > 0 THEN 'D' WHEN count_if(upper((ec.card_type)) = 'DI') > 0 THEN 'DI' WHEN count_if(upper((ec.card_type)) = 'A') > 0 THEN 'A' ELSE NULL END AS debit_type, CASE WHEN count_if(upper((ec.card_type)) = 'PC') > 0 THEN 'PC' WHEN count_if(upper((ec.card_type)) = 'C') > 0 THEN 'C' ELSE NULL END AS credit_type FROM\"AwsDataCatalog\".\"silver_know\".\"eft_card_file\" ec WHERE ec.credit_union = '{credit_union_q}' GROUP BY ec.credit_union, ec.member_number ) SELECT fi.idfi AS idfi, f.period, CASE WHEN f.tran_prefix = 'DRWD' THEN CASE mct.debit_type WHEN 'D' THEN 'Debit' WHEN 'DI' THEN 'Debit Instant' WHEN 'A' THEN 'ATM' ELSE 'Debit (No Card)' END WHEN f.tran_prefix = 'TLT' THEN CASE mct.credit_type WHEN 'PC' THEN 'Credit Platinum' WHEN 'C' THEN 'Credit Gold' ELSE 'Credit (Unknown)' END ELSE 'Other' END AS specific_card_type, COUNT(DISTINCT f.member_id) AS unique_members, COUNT( DISTINCT CASE WHEN f.tran_prefix = 'DRWD' THEN concat('DEBIT_', CAST(f.account_id AS varchar), '', CAST(f.member_id AS varchar)) WHEN f.tran_prefix = 'TLT' THEN concat('CREDIT', CAST(f.account_id AS varchar)) ELSE concat('ACCOUNT_', CAST(f.account_id AS varchar)) END ) AS unique_cards, COUNT(DISTINCT f.transaction_history_id) AS total_transactions, ROUND(AVG(ABS(f.total_amount)), 2) AS avg_transaction_amount, ROUND(SUM(ABS(f.total_amount)), 2) AS total_transaction_volume FROM filtered_th f JOIN\"AwsDataCatalog\".\"silver_know\".\"account\" a ON a.account_id = f.account_id AND a.credit_union = f.credit_union LEFT JOIN member_card_types mct ON mct.member_number = a.member_number AND mct.credit_union = a.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = '{credit_union_q}' WHERE f.credit_union = '{credit_union_q}' GROUP BY fi.idfi, f.period, CASE WHEN f.tran_prefix = 'DRWD' THEN CASE mct.debit_type WHEN 'D' THEN 'Debit' WHEN 'DI' THEN 'Debit Instant' WHEN 'A' THEN 'ATM' ELSE 'Debit (No Card)' END WHEN f.tran_prefix = 'TLT' THEN CASE mct.credit_type WHEN 'PC' THEN 'Credit Platinum' WHEN 'C' THEN 'Credit Gold' ELSE 'Credit (Unknown)' END ELSE 'Other' END ORDER BY fi.idfi DESC, f.period ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_gl_accounts_general = f"UNLOAD (WITH months AS ( SELECT CAST(period_start AS date) AS period_start FROM UNNEST(sequence(DATE '2022-01-01', date_trunc('month', current_date), INTERVAL '1' MONTH)) AS t(period_start) ), acct AS ( SELECT g.credit_union, CAST(g.account_number AS varchar) AS account_number, g.description, g.short_desc, UPPER(TRIM(g.account_type)) AS account_type, g.inactive, CAST(g.created_timestamp AS timestamp(3)) AS created_timestamp, CAST(g.modified_timestamp AS timestamp(3)) AS modified_timestamp, g.restricted, g.controlled, g.modified_by_userid, g.balance AS current_balance_from_coa FROM \"AwsDataCatalog\".\"silver_know\".\"gl_chart_of_accounts\" g WHERE g.credit_union = '{credit_union_q}' AND UPPER(TRIM(g.account_type)) IN ('B','I') ), monthly_stats AS ( SELECT h.credit_union, CAST(h.gl_account_number AS varchar) AS account_number, CAST(date_trunc('month', h.effective_date) AS date) AS period_start, COUNT(*) AS transaction_count, SUM(CASE WHEN h.amount < 0 THEN -h.amount ELSE 0 END) AS total_debits, SUM(CASE WHEN h.amount > 0 THEN h.amount ELSE 0 END) AS total_credits, SUM(h.amount) AS net_activity, SUM(ABS(h.amount)) AS total_amount FROM \"AwsDataCatalog\".\"silver_know\".\"gl_history\" h WHERE h.credit_union = '{credit_union_q}' AND h.effective_date >= DATE '2022-01-01' GROUP BY h.credit_union, CAST(h.gl_account_number AS varchar), CAST(date_trunc('month', h.effective_date) AS date) ), grid AS ( SELECT a.credit_union, a.account_number, m.period_start FROM acct a JOIN months m ON m.period_start >= date_add('month', -36, date_trunc('month', current_date)) ), stats AS ( SELECT g.credit_union, g.account_number, g.period_start, COALESCE(ms.transaction_count, 0) AS monthly_transactions, COALESCE(ms.total_debits, 0.00) AS monthly_debits, COALESCE(ms.total_credits, 0.00) AS monthly_credits, COALESCE(ms.net_activity, 0.00) AS monthly_net_activity, COALESCE(ms.total_amount, 0.00) AS monthly_total_amount FROM grid g LEFT JOIN monthly_stats ms ON ms.credit_union = g.credit_union AND ms.account_number = g.account_number AND ms.period_start = g.period_start ), running AS ( SELECT s.*, SUM(s.monthly_net_activity) OVER ( PARTITION BY s.credit_union, s.account_number ORDER BY s.period_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS calculated_balance FROM stats s ) SELECT fi.idfi AS idfi, CAST(r.period_start AS date) AS Period_Date, date_format(CAST(r.period_start AS timestamp), '%Y-%m') AS Period_Year_Month, year(r.period_start) AS Year, month(r.period_start) AS Month, format_datetime(CAST(r.period_start AS timestamp), 'MMMM') AS Month_Name, a.account_number AS GL_ID, a.description AS GL_Name, a.short_desc AS Short_Description, CASE WHEN a.account_type = 'B' THEN 'Balance Sheet' WHEN a.account_type = 'I' THEN 'Income Statement' ELSE 'Other' END AS GL_Category, CASE WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 701 AND 799 AND r.calculated_balance > 0 THEN 'ASSETS - Loans to Members' WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 740 AND 750 AND r.calculated_balance > 0 THEN 'ASSETS - Investments' WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 770 AND 780 AND r.calculated_balance > 0 THEN 'ASSETS - Property & Equipment' WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 700 AND 799 AND r.calculated_balance < 0 THEN 'CONTRA-ASSETS - Allowances/Provisions' WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 800 AND 899 AND r.calculated_balance < 0 THEN 'LIABILITIES - Accounts Payable' WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 900 AND 989 AND r.calculated_balance < 0 THEN 'LIABILITIES - Member Deposits' WHEN a.account_type = 'B' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 990 AND 999 AND r.calculated_balance < 0 THEN 'EQUITY - Capital & Reserves' WHEN a.account_type = 'I' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 110 AND 199 THEN 'INCOME - Interest & Fees' WHEN a.account_type = 'I' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 200 AND 299 THEN 'EXPENSES - Personnel' WHEN a.account_type = 'I' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 300 AND 399 THEN 'EXPENSES - Operations' WHEN a.account_type = 'I' AND try_cast(split_part(a.account_number, '.', 1) AS integer) BETWEEN 400 AND 499 THEN 'OTHER - Income/Expense' ELSE 'OTHER' END AS GL_Subcategory, CASE WHEN a.account_type = 'B' AND a.current_balance_from_coa > 0 THEN 'ASSET' WHEN a.account_type = 'B' AND a.current_balance_from_coa < 0 THEN 'LIABILITY/EQUITY' WHEN a.account_type = 'B' AND a.current_balance_from_coa = 0 THEN 'ZERO BALANCE' WHEN a.account_type = 'I' THEN 'INCOME/EXPENSE' ELSE 'OTHER' END AS Asset_Liability_Type, CASE WHEN a.inactive = 0 THEN 'Active' ELSE 'Inactive' END AS Status, a.created_timestamp AS Open_Date, CASE WHEN a.inactive = 1 THEN a.modified_timestamp ELSE NULL END AS Close_Date, r.calculated_balance AS Historical_Balance, a.current_balance_from_coa AS Current_Balance_From_COA, (r.calculated_balance - LAG(r.calculated_balance, 1) OVER (PARTITION BY r.credit_union, r.account_number ORDER BY r.period_start)) AS Period_Balance_Change, r.monthly_transactions AS Monthly_Transaction_Count, r.monthly_debits AS Monthly_Debits, r.monthly_credits AS Monthly_Credits, r.monthly_net_activity AS Monthly_Net_Activity, r.monthly_total_amount AS Monthly_Total_Amount, CASE WHEN COALESCE(r.monthly_transactions, 0) = 0 THEN 'No Activity' WHEN r.monthly_transactions <= 10 THEN 'Low Activity' WHEN r.monthly_transactions <= 50 THEN 'Medium Activity' WHEN r.monthly_transactions <= 200 THEN 'High Activity' ELSE 'Very High Activity' END AS Activity_Level, CASE WHEN a.restricted = 1 THEN 'Yes' ELSE 'No' END AS Restricted, CASE WHEN UPPER(TRIM(CAST(a.controlled AS varchar))) = 'Y' THEN 'Yes' ELSE 'No' END AS Controlled, a.modified_timestamp AS Last_Modified, a.modified_by_userid AS Last_Modified_By FROM running r JOIN acct a ON a.account_number = r.account_number AND a.credit_union = r.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = r.credit_union ORDER BY r.period_start DESC, a.account_type, a.account_number ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_gl_accounts_transactions = f"UNLOAD ( SELECT h.record_number AS transaction_id, CAST(h.gl_account_number AS varchar) AS gl_id, gl.description AS gl_name, gl.short_desc AS gl_short_name, h.description AS transaction_description, CONCAT(CAST(h.gl_account_number AS varchar), '-', gl.short_desc) AS gl_account_concat, h.branch_config_id AS branch_config_id, bc.branch_number AS branch_number, CASE WHEN be.name_last = 'MINNEQUA WORKS CREDIT UNION - PAULINE MONTOYA' THEN 'MINNEQUA WORKS CR' WHEN be.name_last IS NULL THEN 'Unknown Branch' ELSE TRIM(be.name_last) END AS branch_name, CASE WHEN bc.branch_number = '0' THEN 'HEADQUARTERS/CORPORATE' WHEN bc.branch_number = '1' THEN 'MAIN_BRANCH/PRIMARY' WHEN bc.branch_number = '2' THEN 'REGENCY/BUSINESS_SERVICES' WHEN bc.branch_number = '3' THEN 'PUEBLO_WEST/COMMUNITY' WHEN bc.branch_number = '4' THEN 'EAGLERIDGE/HIGH_VOLUME' WHEN bc.branch_number = '5' THEN 'NEPCO/MIXED_SERVICES' WHEN bc.branch_number = '6' THEN 'REMOTE_SERVICES/DIGITAL' ELSE 'OTHER_BRANCH' END AS branch_category, CASE WHEN bc.branch_number = '0' THEN 'VERY_HIGH_ACTIVITY' WHEN bc.branch_number = '1' THEN 'HIGHEST_ACTIVITY' WHEN bc.branch_number = '4' THEN 'HIGH_ACTIVITY' WHEN bc.branch_number = '5' THEN 'MEDIUM_ACTIVITY' WHEN bc.branch_number = '3' THEN 'LOW_ACTIVITY' WHEN bc.branch_number = '2' THEN 'MINIMAL_ACTIVITY' WHEN bc.branch_number = '6' THEN 'DIGITAL_ONLY' ELSE 'UNKNOWN_ACTIVITY' END AS branch_activity_level, CASE WHEN bc.branch_number = '0' THEN 'Corporate/Administrative Members' WHEN bc.branch_number = '1' THEN 'Family/General Membership' WHEN bc.branch_number = '4' THEN 'Family/Community Focused' WHEN bc.branch_number = '5' THEN 'Mixed Community/Business' WHEN bc.branch_number = '3' THEN 'Family/Community Satellite' WHEN bc.branch_number = '2' THEN 'Customer/Business Services' WHEN bc.branch_number = '6' THEN 'Digital/Remote Services' ELSE 'Unknown Specialization' END AS branch_specialization, CASE WHEN bc.branch_number = '1' THEN 'HIGHEST_DENSITY' WHEN bc.branch_number = '0' THEN 'VERY_HIGH_DENSITY' WHEN bc.branch_number = '4' THEN 'HIGH_DENSITY' WHEN bc.branch_number = '5' THEN 'MEDIUM_DENSITY' WHEN bc.branch_number = '3' THEN 'LOW_DENSITY' WHEN bc.branch_number = '2' THEN 'MINIMAL_DENSITY' WHEN bc.branch_number = '6' THEN 'ULTRA_LOW_DENSITY' ELSE 'UNKNOWN_DENSITY' END AS branch_member_density, gl.account_type AS account_type, CASE WHEN gl.account_type = 'B' THEN 'Balance Sheet' WHEN gl.account_type = 'I' THEN 'Income Statement' ELSE 'Other' END AS account_category, CASE WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 799 THEN 'ASSETS - Loans & Investments' WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 800 AND 899 THEN 'ASSETS/LIABILITIES - Clearing & Payables' WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 THEN 'LIABILITIES - Deposits & Equity' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'INCOME - Interest & Fees' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 299 THEN 'EXPENSES - Personnel & Operations' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 300 AND 399 THEN 'EXPENSES - Operations & Provisions' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 400 AND 499 THEN 'OTHER - Miscellaneous Income/Expense' ELSE 'OTHER' END AS gl_subcategory, CASE WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 THEN 'DEBIT_NATURE' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 THEN 'DEBIT_NATURE' WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 THEN 'CREDIT_NATURE' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'CREDIT_NATURE' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 400 AND 499 THEN 'CREDIT_NATURE' ELSE 'MIXED_NATURE' END AS account_nature, CASE WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 THEN 'ASSETS (Increase with Debits, Decrease with Credits)' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 THEN 'EXPENSES (Increase with Debits, Decrease with Credits)' WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 THEN 'LIABILITIES/EQUITY (Increase with Credits, Decrease with Debits)' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'REVENUE (Increase with Credits, Decrease with Debits)' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 400 AND 499 THEN 'OTHER REVENUE (Increase with Credits, Decrease with Debits)' ELSE 'MIXED OR UNCLASSIFIED NATURE' END AS account_nature_description, h.effective_date AS effective_date, h.reference_date AS reference_date, h.actual_date AS posting_date, date_format(CAST(h.effective_date AS timestamp), '%Y-%m') AS yearmonth, year(h.effective_date) AS transactionyear, month(h.effective_date) AS transactionmonth, date_format(CAST(h.effective_date AS timestamp), 'MMMM') AS monthname, quarter(h.effective_date) AS transactionquarter, day(h.effective_date) AS dayofmonth, date_format(CAST(h.effective_date AS timestamp), 'EEEE') AS dayofweek, day_of_week(h.effective_date) AS dayofweeknumber, week(h.effective_date) AS isoweek, day_of_year(h.effective_date) AS dayofyear, CASE WHEN day_of_week(h.effective_date) IN (6, 7) THEN 'Weekend' ELSE 'Weekday' END AS businessdaytype, CASE WHEN day(h.effective_date) <= 7 THEN 'First Week' WHEN day(h.effective_date) <= 14 THEN 'Second Week' WHEN day(h.effective_date) <= 21 THEN 'Third Week' ELSE 'Fourth Week+' END AS weekofmonth, h.source AS txn_source, CASE WHEN h.source = 'CU' THEN 'Credit Union System (EOD Processing)' WHEN h.source = 'JE' THEN 'Journal Entry (Manual/System)' WHEN h.source = 'CT' THEN 'Certificate/Time Deposit' WHEN h.source = 'AP' THEN 'Accounts Payable' WHEN h.source = 'FA' THEN 'Fixed Assets' WHEN h.source = 'PR' THEN 'Payroll' ELSE 'Other/Unknown' END AS source_description, h.entry_desc AS entry_desc, CASE WHEN h.entry_desc = 'EOD' THEN 'End of Day Processing' WHEN h.entry_desc LIKE '%-%' THEN 'Manual/Specific Entry' ELSE 'Standard Entry' END AS entry_description, h.amount AS amount, ABS(h.amount) AS abs_amount, CASE WHEN h.amount > 0 THEN 'Debit' WHEN h.amount < 0 THEN 'Credit' ELSE 'Zero' END AS debit_credit, CASE WHEN h.amount > 0 AND gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 THEN 'Increases Asset Account' WHEN h.amount < 0 AND gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 THEN 'Decreases Asset Account' WHEN h.amount > 0 AND gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 THEN 'Increases Expense Account' WHEN h.amount < 0 AND gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 THEN 'Decreases Expense Account' WHEN h.amount < 0 AND gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 THEN 'Increases Liability/Equity Account' WHEN h.amount > 0 AND gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 THEN 'Decreases Liability/Equity Account' WHEN h.amount < 0 AND gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'Increases Revenue Account' WHEN h.amount > 0 AND gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'Decreases Revenue Account' ELSE 'Other Impact' END AS account_impact_description, CASE WHEN ABS(h.amount) = 0 THEN 'Zero Amount' WHEN ABS(h.amount) < 100 THEN 'Small (< $100)' WHEN ABS(h.amount) < 1000 THEN 'Medium ($100 - $1K)' WHEN ABS(h.amount) < 10000 THEN 'Large ($1K - $10K)' WHEN ABS(h.amount) < 100000 THEN 'Very Large ($10K - $100K)' ELSE 'Exceptional ($100K+)' END AS transaction_size_category, h.batch_number AS batch_number, h.group_id AS group_id, h.group_seq AS group_sequence, h.posted_by_user AS posted_by_user, CASE WHEN UPPER(h.description) LIKE '%DIVIDEND%' OR UPPER(h.description) LIKE '%DIV-%' THEN 'Dividend Transaction' WHEN UPPER(h.description) LIKE '%INTEREST%' OR UPPER(h.description) LIKE '%INT-%' THEN 'Interest Transaction' WHEN UPPER(h.description) LIKE '%FEE%' OR UPPER(h.description) LIKE '%CHARGE%' THEN 'Fee Transaction' WHEN UPPER(h.description) LIKE '%SUMMARY%' THEN 'Summary/Aggregated Transaction' WHEN UPPER(h.description) LIKE '%ACCRUAL%' OR UPPER(h.description) LIKE '%ACCR%' THEN 'Accrual Transaction' WHEN UPPER(h.description) LIKE '%REVERSAL%' OR UPPER(h.description) LIKE '%REV%' THEN 'Reversal Transaction' WHEN UPPER(h.description) LIKE '%CORRECTION%' OR UPPER(h.description) LIKE '%CORR%' THEN 'Correction Transaction' WHEN UPPER(h.description) LIKE '%ADJUSTMENT%' OR UPPER(h.description) LIKE '%ADJ%' THEN 'Adjustment Transaction' ELSE 'Regular Transaction' END AS transaction_nature, CASE WHEN h.source = 'CU' AND h.entry_desc = 'EOD' THEN 'Automated EOD' WHEN h.source = 'JE' AND h.entry_desc LIKE '%-%' THEN 'Manual Entry' WHEN h.source IN ('CT', 'AP', 'FA') THEN 'System Generated' ELSE 'Other Processing' END AS processing_type, h.status AS record_status, h.modified AS modified_flag, h.version AS record_version, h.created_timestamp AS record_created, h.created_by_userid AS created_by_user, h.modified_timestamp AS record_modified, h.modified_by_userid AS modified_by_user, fi.idfi AS idfi, gl.inactive AS account_inactive, gl.restricted AS account_restricted, gl.controlled AS account_controlled, gl.balance AS current_account_balance, CASE WHEN ABS(h.amount) > 500000 THEN 'Exceptional Volume' WHEN ABS(h.amount) > 100000 THEN 'Very High Volume' WHEN ABS(h.amount) > 10000 THEN 'High Volume' ELSE 'Standard Volume' END AS volume_indicator, CASE WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 860 AND 899 THEN 'High Activity Account' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'High Activity Account' ELSE 'Standard Activity Account' END AS expected_activity_level, CASE WHEN (gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 AND h.amount > 0) OR (gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 AND h.amount > 0) OR (gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 AND h.amount < 0) OR (gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 AND h.amount < 0) OR (gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 400 AND 499 AND h.amount < 0) THEN 'NORMAL_PATTERN' WHEN (gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 AND h.amount < 0) OR (gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 AND h.amount < 0) OR (gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 AND h.amount > 0) OR (gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 AND h.amount > 0) OR (gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 400 AND 499 AND h.amount > 0) THEN 'CONTRA_PATTERN' ELSE 'UNDEFINED_PATTERN' END AS transaction_pattern, CASE WHEN h.amount = 0 THEN 'ZERO_RISK' WHEN ABS(h.amount) > 100000 AND ((gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 AND h.amount < 0) OR (gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 AND h.amount > 0)) THEN 'HIGH_RISK_LARGE_CONTRA' WHEN h.source = 'JE' AND h.entry_desc LIKE '%-%' AND ABS(h.amount) > 10000 THEN 'MEDIUM_RISK_MANUAL_LARGE' WHEN UPPER(h.description) LIKE '%REVERSAL%' OR UPPER(h.description) LIKE '%CORRECTION%' THEN 'MEDIUM_RISK_ADJUSTMENT' ELSE 'LOW_RISK' END AS risk_level, CASE WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 700 AND 899 THEN 'ASSETS' WHEN gl.account_type = 'B' AND CAST(gl.account_number AS integer) BETWEEN 900 AND 999 THEN 'LIABILITIES_EQUITY' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 110 AND 199 THEN 'REVENUE' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 200 AND 399 THEN 'EXPENSES' WHEN gl.account_type = 'I' AND CAST(gl.account_number AS integer) BETWEEN 400 AND 499 THEN 'OTHER_INCOME' ELSE 'UNCATEGORIZED' END AS accounting_category, CASE WHEN bc.branch_number = '0' AND ABS(h.amount) > 1000000 THEN 'HQ_LARGE_TRANSACTION' WHEN bc.branch_number != '0' AND ABS(h.amount) > 100000 THEN 'BRANCH_LARGE_TRANSACTION' WHEN bc.branch_number = '6' AND ABS(h.amount) > 1000 THEN 'REMOTE_UNUSUAL_AMOUNT' ELSE 'NORMAL_BRANCH_TRANSACTION' END AS branch_transaction_pattern, CASE WHEN h.source = 'JE' AND bc.branch_number != '0' THEN 'BRANCH_MANUAL_ENTRY' WHEN h.source = 'CU' AND bc.branch_number = '0' THEN 'HQ_SYSTEM_TRANSACTION' WHEN h.source = 'CU' AND bc.branch_number != '0' THEN 'BRANCH_SYSTEM_TRANSACTION' ELSE 'OTHER_BRANCH_TRANSACTION' END AS branch_transaction_type FROM \"AwsDataCatalog\".\"silver_know\".\"gl_history\" h INNER JOIN \"AwsDataCatalog\".\"silver_know\".\"gl_chart_of_accounts\" gl ON gl.account_number = h.gl_account_number AND gl.credit_union = h.credit_union LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"branch_config\" bc ON h.branch_config_id = bc.branch_config_id AND bc.credit_union = h.credit_union LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"entity\" be ON bc.branch_entity_id = be.entity_id AND be.credit_union = h.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = h.credit_union WHERE h.credit_union = '{credit_union_q}' AND h.effective_date >= date_add('month', -36, current_date) AND gl.account_type IN ('B','I') ORDER BY h.effective_date DESC, h.record_number DESC ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_gl_certs = f"UNLOAD (WITH cert_paid_accounts AS ( SELECT DISTINCT at.credit_union AS credit_union, COALESCE(REGEXP_REPLACE(TRIM(CAST(at.div_int_acct AS varchar)), '^0+', ''), '0') AS paid_gl_account_canon FROM\"AwsDataCatalog\".\"silver_know\".\"account_types\" at WHERE at.category = 'CERT' AND at.div_int_acct IS NOT NULL AND credit_union='{credit_union_q}' ), cert_accrual_accounts AS ( SELECT DISTINCT at.credit_union AS credit_union, COALESCE(REGEXP_REPLACE(TRIM(CAST(at.accrual_acct AS varchar)), '^0+', ''), '0') AS accrual_gl_account_canon FROM\"AwsDataCatalog\".\"silver_know\".\"account_types\" at WHERE at.category = 'CERT' AND at.accrual_acct IS NOT NULL AND credit_union='{credit_union_q}' ), gl_hist AS ( SELECT gh.*, COALESCE(REGEXP_REPLACE((CAST(gh.gl_account_number AS varchar)), '^0+', ''), '0') AS gl_account_canon FROM\"AwsDataCatalog\".\"silver_know\".\"gl_history\" gh WHERE UPPER((COALESCE(gh.status,'P'))) = 'P' AND credit_union='{credit_union_q}' ), monthly_div_int_amounts AS ( SELECT year(gh.effective_date) AS entry_year, month(gh.effective_date) AS entry_month, quarter(gh.effective_date) AS entry_quarter, date_format(gh.effective_date, '%Y-%m') AS yearMonth, SUM(gh.amount) AS div_int_balance, COUNT(DISTINCT gh.batch_number) AS div_int_transaction_count, COUNT() AS div_int_gl_entry_count, MIN(gh.effective_date) AS div_int_earliest_date, MAX(gh.effective_date) AS div_int_latest_date FROM gl_hist gh JOIN cert_paid_accounts cpa ON gh.gl_account_canon = cpa.paid_gl_account_canon GROUP BY year(gh.effective_date), month(gh.effective_date), quarter(gh.effective_date), date_format(gh.effective_date, '%Y-%m') ), monthly_accrual_amounts AS ( SELECT year(gh.effective_date) AS entry_year, month(gh.effective_date) AS entry_month, quarter(gh.effective_date) AS entry_quarter, date_format(gh.effective_date, '%Y-%m') AS yearMonth, SUM(gh.amount) AS total_accrued_amount, COUNT(DISTINCT gh.batch_number) AS actual_transaction_count, COUNT(*) AS gl_entry_count, MIN(gh.effective_date) AS earliest_transaction_date, MAX(gh.effective_date) AS latest_transaction_date FROM gl_hist gh JOIN cert_accrual_accounts caa ON gh.gl_account_canon = caa.accrual_gl_account_canon GROUP BY year(gh.effective_date), month(gh.effective_date), quarter(gh.effective_date), date_format(gh.effective_date, '%Y-%m') ) SELECT fi.idfi AS idfi, 'CERT' AS product_type, 'Dividend' AS transaction_type, mda.entry_year, mda.entry_month, mda.entry_quarter, mda.yearMonth, (mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) AS total_paid_amount, COALESCE(maa.total_accrued_amount, 0) AS total_accrued_amount, (mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) - COALESCE(maa.total_accrued_amount, 0) AS variance_paid_vs_accrued, CASE WHEN COALESCE(maa.total_accrued_amount, 0) > 0 THEN ROUND(((mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) / maa.total_accrued_amount) * 100, 2) ELSE NULL END AS paid_to_accrued_ratio_pct, mda.div_int_transaction_count AS paid_transaction_count, COALESCE(maa.actual_transaction_count, 0) AS accrued_transaction_count, mda.div_int_gl_entry_count AS paid_gl_entries, COALESCE(maa.gl_entry_count, 0) AS accrued_gl_entries, mda.div_int_earliest_date AS paid_earliest_date, mda.div_int_latest_date AS paid_latest_date, maa.earliest_transaction_date AS accrued_earliest_date, maa.latest_transaction_date AS accrued_latest_date, CASE WHEN (mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) > 0 AND COALESCE(maa.total_accrued_amount, 0) = 0 THEN 'PAID_WITHOUT_ACCRUAL' WHEN (mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) = 0 AND COALESCE(maa.total_accrued_amount, 0) > 0 THEN 'ACCRUED_NOT_PAID' WHEN ABS((mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) - COALESCE(maa.total_accrued_amount, 0)) > (ABS(mda.div_int_balance - COALESCE(maa.total_accrued_amount, 0)) * 0.05) THEN 'SIGNIFICANT_VARIANCE' ELSE 'NORMAL' END AS alert_status, CASE WHEN maa.earliest_transaction_date IS NOT NULL AND mda.div_int_latest_date IS NOT NULL THEN date_diff('day', maa.earliest_transaction_date, mda.div_int_latest_date) ELSE NULL END AS days_between_accrual_and_payment FROM monthly_div_int_amounts mda LEFT JOIN monthly_accrual_amounts maa ON mda.yearMonth = maa.yearMonth LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(trim(fi.prodigy_code)) = '{credit_union_q}' WHERE mda.yearMonth IS NOT NULL UNION SELECT fi.idfi AS idfi, 'CERT' AS product_type, 'Dividend' AS transaction_type, maa.entry_year, maa.entry_month, maa.entry_quarter, maa.yearMonth, (0 - maa.total_accrued_amount) AS total_paid_amount, maa.total_accrued_amount, (0 - maa.total_accrued_amount) - maa.total_accrued_amount AS variance_paid_vs_accrued, CASE WHEN maa.total_accrued_amount > 0 THEN ROUND(((0 - maa.total_accrued_amount) / maa.total_accrued_amount) * 100, 2) ELSE NULL END AS paid_to_accrued_ratio_pct, 0 AS paid_transaction_count, maa.actual_transaction_count AS accrued_transaction_count, 0 AS paid_gl_entries, maa.gl_entry_count AS accrued_gl_entries, NULL AS paid_earliest_date, NULL AS paid_latest_date, maa.earliest_transaction_date AS accrued_earliest_date, maa.latest_transaction_date AS accrued_latest_date, 'ACCRUED_NOT_PAID' AS alert_status, NULL AS days_between_accrual_and_payment FROM monthly_accrual_amounts maa LEFT JOIN monthly_div_int_amounts mda ON maa.yearMonth = mda.yearMonth LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(trim(fi.prodigy_code)) = '{credit_union_q}' WHERE mda.yearMonth IS NULL AND maa.total_accrued_amount <> 0 ORDER BY entry_year DESC, entry_month DESC ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_gl_dividends = f"UNLOAD ( WITH th_base AS ( SELECT th.credit_union AS credit_union, th.transaction_history_id, th.batch_number, th.tran_code AS tran_code_raw, UPPER(CAST(th.tran_code AS varchar)) AS tran_code_norm, th.date_effective, th.total_amount, th.member_id, th.account_id, th.gl_chart_of_account_id, th.branch_config_id, COALESCE(th.void_flag, 0) AS void_flag_norm, th.user_id, th.description, th.created_timestamp, th.modified_timestamp FROM \"AwsDataCatalog\".\"silver_know\".\"transaction_history\" th WHERE th.date_effective >= date_add('month', -12, current_date) AND th.credit_union = '{credit_union_q}' AND UPPER(CAST(th.tran_code AS varchar)) IN ('SHDV','CTDV') AND COALESCE(th.void_flag, 0) = 0 AND th.total_amount <> 0 ), dim_member AS ( SELECT m.credit_union AS credit_union, m.member_id, m.member_number FROM \"AwsDataCatalog\".\"silver_know\".\"member\" m WHERE m.credit_union = '{credit_union_q}' ), dim_account AS ( SELECT a.credit_union AS credit_union, a.account_id, a.account_number, a.account_type AS account_type_raw, UPPER(CAST(a.account_type AS varchar)) AS account_type_norm, a.discriminator AS discriminator_raw, UPPER(CAST(a.discriminator AS varchar)) AS discriminator_norm, a.current_balance, a.status FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a WHERE a.credit_union = '{credit_union_q}' ), dim_branch AS ( SELECT bc.credit_union AS credit_union, bc.branch_config_id, CAST(bc.branch_number AS varchar) AS branch_number_norm, be_branch.name_last AS branch_name FROM \"AwsDataCatalog\".\"silver_know\".\"branch_config\" bc LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"entity\" be_branch ON be_branch.entity_id = bc.branch_entity_id AND be_branch.credit_union = '{credit_union_q}' AND be_branch.credit_union = bc.credit_union WHERE bc.credit_union = '{credit_union_q}' ), dim_coa AS ( SELECT gcoa.credit_union AS credit_union, gcoa.record_number, CAST(gcoa.account_number AS varchar) AS account_number_str, gcoa.description, gcoa.short_desc FROM \"AwsDataCatalog\".\"silver_know\".\"gl_chart_of_accounts\" gcoa WHERE gcoa.credit_union = '{credit_union_q}' ) SELECT fi.idfi AS idfi, CONCAT('TXN_', th.tran_code_norm, '', CAST(th.transaction_history_id AS varchar)) AS ID_Dividend_Transaction, th.transaction_history_id AS Transaction_History_ID, th.batch_number AS Batch_Number, th.tran_code_norm AS Transaction_Code, CASE WHEN th.tran_code_norm = 'SHDV' THEN 'SHARE_DIVIDEND_TO_MEMBER' WHEN th.tran_code_norm = 'CTDV' THEN 'CERTIFICATE_DIVIDEND' ELSE CONCAT('OTHER_DIVIDEND', th.tran_code_norm) END AS Transaction_Type, th.date_effective AS Transaction_Date, year(th.date_effective) AS Transaction_Year, month(th.date_effective) AS Transaction_Month, quarter(th.date_effective) AS Transaction_Quarter, date_format(CAST(th.date_effective AS timestamp), 'yyyy-MM') AS year_month, th.total_amount AS Amount, abs(th.total_amount) AS Amount_Absolute, th.member_id AS Member_ID, dm.member_number AS Member_Number, th.account_id AS Account_ID, da.account_number AS Account_Number, da.account_type_raw AS Account_Type, da.discriminator_raw AS Account_Discriminator, CASE WHEN da.discriminator_norm = 'S' THEN 'SAVINGS' WHEN da.discriminator_norm = 'C' THEN 'CERTIFICATES' WHEN da.discriminator_norm = 'D' THEN 'CHECKING' WHEN da.discriminator_norm = 'L' THEN 'LOANS' WHEN da.discriminator_norm = 'U' THEN 'SPECIAL' ELSE 'OTHER' END AS Account_Category, CASE WHEN da.discriminator_norm = 'S' THEN CASE WHEN da.account_type_norm = 'PSAV' THEN 'Primary Savings' WHEN da.account_type_norm = 'HYS' THEN 'High Yield Savings' WHEN da.account_type_norm = 'MMA' THEN 'Money Market' WHEN da.account_type_norm = 'SSAV' THEN 'Secondary Savings' WHEN da.account_type_norm = 'CLUB' THEN 'Club Account' WHEN da.account_type_norm = 'TISV' THEN 'Traditional IRA Savings' WHEN da.account_type_norm = 'RISV' THEN 'Roth IRA Savings' WHEN da.account_type_norm = 'YSAV' THEN 'Youth Savings' WHEN da.account_type_norm = 'SPIS' THEN 'SEP IRA Savings' ELSE CONCAT(da.discriminator_raw, ' - ', da.account_type_raw) END WHEN da.discriminator_norm = 'C' THEN CASE WHEN da.account_type_norm = 'CERT' THEN 'Certificate of Deposit' WHEN da.account_type_norm = 'TICD' THEN 'Traditional IRA Certificate' WHEN da.account_type_norm = 'RICD' THEN 'Roth IRA Certificate' WHEN da.account_type_norm = 'EICD' THEN 'Education IRA Certificate' ELSE CONCAT(da.discriminator_raw, ' - ', da.account_type_raw) END WHEN da.discriminator_norm = 'D' AND da.account_type_norm = 'CHK' THEN 'Checking Account' WHEN da.discriminator_norm = 'D' AND da.account_type_norm = 'OTCK' THEN 'Overtime Checking' WHEN da.discriminator_norm = 'L' THEN 'LOANS' WHEN da.discriminator_norm = 'U' THEN 'SPECIAL' ELSE 'OTHER' END AS Product_Type, da.current_balance AS Current_Account_Balance, da.status AS Account_Status, gl.account_number_str AS GL_Account_Number, gl.description AS GL_Account_Description, gl.short_desc AS GL_Account_Short_Desc, CASE WHEN gl.account_number_str LIKE '380.%' THEN 'DIVIDEND_EXPENSE' WHEN gl.account_number_str LIKE '901.%' THEN 'MEMBER_DEPOSIT_ACCOUNT' WHEN gl.account_number_str LIKE '903.%' THEN 'CERTIFICATE_ACCOUNT' WHEN gl.account_number_str LIKE '383.%' THEN 'OTHER_DIVIDEND_EXPENSE' WHEN gl.account_number_str LIKE '151.%' THEN 'CASH_ACCOUNT' ELSE 'OTHER_GL_ACCOUNT' END AS GL_Account_Category, th.branch_config_id AS Branch_Config_ID, db.branch_number_norm AS Branch_Number, CASE WHEN db.branch_name LIKE '%MINNEQUA WORKS CREDIT UNION%' THEN 'MINNEQUA WORKS CR' WHEN db.branch_name IS NULL THEN 'Unknown Branch' ELSE db.branch_name END AS Branch_Name, CASE WHEN db.branch_number_norm = '0' THEN 'HEADQUARTERS' WHEN db.branch_number_norm = '1' THEN 'MAIN_BRANCH' WHEN db.branch_number_norm = '2' THEN 'REGENCY' WHEN db.branch_number_norm = '3' THEN 'PUEBLO_WEST' WHEN db.branch_number_norm = '4' THEN 'EAGLERIDGE' WHEN db.branch_number_norm = '5' THEN 'NEPCO' WHEN db.branch_number_norm = '6' THEN 'REMOTE_SERVICES' ELSE 'OTHER_BRANCH' END AS Branch_Category, CASE WHEN th.tran_code_norm = 'SHDV' AND da.discriminator_norm = 'S' THEN 'SAVINGS_DIVIDEND_PAYMENT' WHEN th.tran_code_norm = 'CTDV' THEN 'CERTIFICATE_DIVIDEND_PAYMENT' ELSE 'OTHER_DIVIDEND_TRANSACTION' END AS Business_Category, CASE WHEN th.tran_code_norm = 'SHDV' AND da.current_balance > 100 AND th.total_amount < 0 THEN round((abs(th.total_amount) / da.current_balance) * 100, 4) ELSE NULL END AS Estimated_Monthly_Rate_Percent, CASE WHEN th.tran_code_norm = 'SHDV' AND da.current_balance > 100 AND th.total_amount < 0 THEN round((abs(th.total_amount) / da.current_balance) * 1200, 4) ELSE NULL END AS Estimated_Annual_Rate_Percent, CAST(0 AS integer) AS Is_Voided, th.user_id AS User_ID, th.description AS Transaction_Description, CAST(th.created_timestamp AS timestamp) AS Created_Timestamp, CAST(th.modified_timestamp AS timestamp) AS Modified_Timestamp, concat('{credit_union_q}','_',CAST(th.transaction_history_id AS varchar)) AS record_key FROM th_base th LEFT JOIN dim_member dm ON th.member_id = dm.member_id AND th.credit_union = dm.credit_union LEFT JOIN dim_account da ON th.account_id = da.account_id AND th.credit_union = da.credit_union LEFT JOIN dim_coa gl ON th.gl_chart_of_account_id = gl.record_number AND th.credit_union = gl.credit_union LEFT JOIN dim_branch db ON th.branch_config_id = db.branch_config_id AND th.credit_union = db.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(fi.prodigy_code) = '{credit_union_q}' ) TO '{temp_path}' WITH ( format = 'PARQUET', compression = 'SNAPPY' );"
    query_gl_loans = f"UNLOAD ( WITH loan_paid_accounts AS ( SELECT DISTINCT COALESCE(REGEXP_REPLACE((CAST(at.div_int_acct AS varchar)), '^0+', ''), '0') AS paid_gl_account_canon FROM \"AwsDataCatalog\".\"silver_know\".\"account_types\" at WHERE at.category = 'LOAN' AND credit_union = '{credit_union_q}' AND at.div_int_acct IS NOT NULL ), loan_accrual_accounts AS ( SELECT DISTINCT at.credit_union AS credit_union, COALESCE(REGEXP_REPLACE((CAST(at.accrual_acct AS varchar)), '^0+', ''), '0') AS accrual_gl_account_canon FROM \"AwsDataCatalog\".\"silver_know\".\"account_types\" at WHERE at.category = 'LOAN' AND credit_union = '{credit_union_q}' AND at.accrual_acct IS NOT NULL ), gl_hist AS ( SELECT gh.*, COALESCE(REGEXP_REPLACE(TRIM(CAST(gh.gl_account_number AS varchar)), '^0+', ''), '0') AS gl_account_canon FROM \"AwsDataCatalog\".\"silver_know\".\"gl_history\" gh WHERE UPPER((COALESCE(gh.status,'P'))) = 'P' AND credit_union = '{credit_union_q}' ), monthly_paid_amounts AS ( SELECT 'LOAN' AS product_type, 'Interest' AS transaction_type, year(gh.effective_date) AS entry_year, month(gh.effective_date) AS entry_month, quarter(gh.effective_date) AS entry_quarter, date_format(gh.effective_date, '%Y-%m') AS yearMonth, gh.credit_union AS credit_union, SUM(ABS(gh.amount)) AS total_paid_amount, COUNT(DISTINCT gh.batch_number) AS actual_transaction_count, COUNT() AS gl_entry_count, MIN(gh.effective_date) AS earliest_transaction_date, MAX(gh.effective_date) AS latest_transaction_date FROM gl_hist gh JOIN loan_paid_accounts lpa ON gh.gl_account_canon = lpa.paid_gl_account_canon GROUP BY year(gh.effective_date), month(gh.effective_date), quarter(gh.effective_date), date_format(gh.effective_date, '%Y-%m'), gh.credit_union ), monthly_accrued_amounts AS ( SELECT 'LOAN' AS product_type, 'Interest' AS transaction_type, year(gh.effective_date) AS entry_year, month(gh.effective_date) AS entry_month, quarter(gh.effective_date) AS entry_quarter, date_format(gh.effective_date, '%Y-%m') AS yearMonth, gh.credit_union AS credit_union, SUM(gh.amount) AS total_accrued_amount, COUNT(DISTINCT gh.batch_number) AS actual_transaction_count, COUNT(*) AS gl_entry_count, MIN(gh.effective_date) AS earliest_transaction_date, MAX(gh.effective_date) AS latest_transaction_date FROM gl_hist gh JOIN loan_accrual_accounts laa ON gh.gl_account_canon = laa.accrual_gl_account_canon AND gh.credit_union = laa.credit_union GROUP BY year(gh.effective_date), month(gh.effective_date), quarter(gh.effective_date), date_format(gh.effective_date, '%Y-%m'), gh.credit_union ) SELECT fi.idfi AS idfi, pa.product_type, pa.transaction_type, pa.entry_year, pa.entry_month, pa.entry_quarter, pa.yearMonth, pa.total_paid_amount, COALESCE(aa.total_accrued_amount, 0) AS total_accrued_amount, pa.total_paid_amount - COALESCE(aa.total_accrued_amount, 0) AS variance_paid_vs_accrued, CASE WHEN COALESCE(aa.total_accrued_amount, 0) > 0 THEN ROUND((pa.total_paid_amount / aa.total_accrued_amount) * 100, 2) ELSE NULL END AS paid_to_accrued_ratio_pct, pa.actual_transaction_count AS paid_transaction_count, COALESCE(aa.actual_transaction_count, 0) AS accrued_transaction_count, pa.gl_entry_count AS paid_gl_entries, COALESCE(aa.gl_entry_count, 0) AS accrued_gl_entries, pa.earliest_transaction_date AS paid_earliest_date, pa.latest_transaction_date AS paid_latest_date, aa.earliest_transaction_date AS accrued_earliest_date, aa.latest_transaction_date AS accrued_latest_date, CASE WHEN pa.total_paid_amount > 0 AND COALESCE(aa.total_accrued_amount, 0) = 0 THEN 'PAID_WITHOUT_ACCRUAL' WHEN pa.total_paid_amount = 0 AND COALESCE(aa.total_accrued_amount, 0) > 0 THEN 'ACCRUED_NOT_PAID' WHEN ABS(pa.total_paid_amount - COALESCE(aa.total_accrued_amount, 0)) > (pa.total_paid_amount * 0.05) THEN 'SIGNIFICANT_VARIANCE' ELSE 'NORMAL' END AS alert_status, CASE WHEN aa.earliest_transaction_date IS NOT NULL AND pa.latest_transaction_date IS NOT NULL THEN date_diff('day', aa.earliest_transaction_date, pa.latest_transaction_date) ELSE NULL END AS days_between_accrual_and_payment FROM monthly_paid_amounts pa LEFT JOIN monthly_accrued_amounts aa ON pa.yearMonth = aa.yearMonth LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(trim(fi.prodigy_code)) = '{credit_union_q}' WHERE pa.yearMonth IS NOT NULL ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY')"
    query_loans_applications = f"UNLOAD (SELECT fi.idfi AS idfi, la.loan_application_id AS application_id, la.member_number AS member_id, la.application_date, la.action_date AS response_date, las.description AS application_status, CASE WHEN COALESCE(TRY_CAST(las.approved_flag AS boolean), false) THEN 'APPROVED' WHEN COALESCE(TRY_CAST(las.adverse_action_flag AS boolean), false) THEN 'DENIED' WHEN COALESCE(TRY_CAST(las.withdrawn_flag AS boolean), false) THEN 'WITHDRAWN' WHEN COALESCE(TRY_CAST(las.incomplete_flag AS boolean), false) THEN 'INCOMPLETE' ELSE 'PENDING' END AS status_category, CASE WHEN la.denial_reason1 IS NOT NULL THEN concat_ws('; ', ARRAY[la.denial_reason1, NULLIF(la.denial_reason2, ''), NULLIF(la.denial_reason3, '')]) WHEN la.loan_app_denial_other IS NOT NULL THEN la.loan_app_denial_other WHEN COALESCE(TRY_CAST(las.approved_flag AS boolean), false) THEN 'APPROVED' WHEN UPPER((las.description)) = 'PENDING' THEN 'UNDER REVIEW' WHEN UPPER((las.description)) = 'WITHDRAW' THEN 'MEMBER WITHDREW' ELSE 'NO REASON SPECIFIED' END AS status_reason, CASE WHEN (la.created_by_userid) IN ('102','103','104','105','106','107','108','109') THEN 'ONLINE' WHEN (la.created_by_userid) = 'SYS' THEN 'SYSTEM/AUTOMATED' WHEN regexp_like((la.created_by_userid), '^[0-9]{1,2}$') THEN 'IN-BRANCH' WHEN la.created_by_userid IS NOT NULL THEN 'STAFF_ASSISTED' ELSE 'UNKNOWN' END AS origination_channel, la.account_id AS loan_id, lt.description AS loan_type, la.loan_amount AS requested_amount, COALESCE(TRY_CAST(la.funded_flag AS boolean), false) AS is_funded, COALESCE(TRY_CAST(la.closed_flag AS boolean), false) AS is_closed, COALESCE(TRY_CAST(la.auto_approved_flag AS boolean), false) AS auto_approved, la.loan_officer_userid AS processing_officer, la.approving_loan_officer_userid AS approving_officer, date_diff('day', la.application_date, COALESCE(la.action_date, current_date)) AS days_to_decision, la.created_timestamp AS application_submitted_timestamp, la.created_by_userid AS submitted_by_user FROM \"AwsDataCatalog\".\"silver_know\".\"loan_application\" la LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"loan_app_status\" las ON la.credit_union = '{credit_union_q}' AND la.credit_union = las.credit_union AND la.loan_app_status_id = las.loan_app_status_id LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"loan_type\" lt ON lt.credit_union = '{credit_union_q}' AND la.credit_union = lt.credit_union AND la.loan_type_id = lt.loan_type_id LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = la.credit_union WHERE la.credit_union = '{credit_union_q}' ORDER BY la.application_date DESC, la.loan_application_id DESC ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_loans_general = f"UNLOAD (WITH cu_info AS ( SELECT DISTINCT credit_union, credit_union_name FROM \"AwsDataCatalog\".\"silver_know\".\"credit_union_info\" WHERE credit_union = '{credit_union_q}' ) SELECT fi.idfi AS idfi, a.member_number AS Member_ID, ci.credit_union_name AS CU_Name, a.account_id AS Loan_ID, at.cb_loan_type AS Credit_Bureau_Code, CASE at.cb_loan_type WHEN '00' THEN 'Auto Loans' WHEN '01' THEN 'Unsecured/Personal Loans' WHEN '02' THEN 'Share/CD Secured Loans' WHEN '03' THEN 'Signature Secured Loans' WHEN '11' THEN 'Recreational Vehicle Loans' WHEN '15' THEN 'Overdraft Protection' WHEN '18' THEN 'Credit Card' WHEN '26' THEN 'Real Estate/Mortgage Loans' WHEN '89' THEN 'Home Equity Loans' ELSE 'Unclassified' END AS Loan_Main_Category, COALESCE(at.description, a.account_type) AS Loan_Sub_Category, a.account_type AS Account_Type_Code, ROUND(al.interest_rate, 3) AS Interest_Rate, al.number_of_payments AS Number_of_Installments, CASE WHEN a.date_closed IS NOT NULL THEN al.number_of_payments WHEN al.number_of_payments IS NOT NULL AND al.number_of_payments > 0 AND a.date_opened IS NOT NULL THEN GREATEST(0, LEAST(al.number_of_payments, CASE WHEN al.payments_per_year > 0 THEN FLOOR(date_diff('day', a.date_opened, COALESCE(a.date_closed, CURRENT_DATE)) * al.payments_per_year / 365.0) ELSE FLOOR(date_diff('day', a.date_opened, COALESCE(a.date_closed, CURRENT_DATE)) / 30.0) END)) ELSE NULL END AS Number_of_Paid_Installments, a.date_opened AS Creation_Date, al.next_payment_date AS Next_Payment_Date, a.date_closed AS Closure_Date, al.credit_score AS Credit_Score, CASE WHEN a.charge_off_date IS NOT NULL THEN 'CHARGED_OFF' WHEN a.date_closed IS NULL AND a.current_balance > 0 AND al.next_payment_date IS NOT NULL AND al.next_payment_date < CURRENT_DATE THEN 'DELINQUENT' WHEN a.current_balance = 0 AND a.date_closed IS NOT NULL AND a.charge_off_date IS NULL AND al.credit_limit = 0 AND al.credit_expiration < CURRENT_DATE THEN 'PAID_OFF' WHEN a.date_closed IS NOT NULL THEN 'CLOSED' ELSE 'ACTIVE' END AS Status, CASE WHEN al.next_payment_date IS NOT NULL AND al.next_payment_date < CURRENT_DATE THEN date_diff('day', al.next_payment_date, CURRENT_DATE) ELSE 0 END AS Days_Past_Due, CASE WHEN al.next_payment_date IS NULL OR al.next_payment_date >= CURRENT_DATE THEN 'CURRENT' WHEN date_diff('day', al.next_payment_date, CURRENT_DATE) BETWEEN 1 AND 30 THEN '1-30 days' WHEN date_diff('day', al.next_payment_date, CURRENT_DATE) BETWEEN 31 AND 60 THEN '31-60 days' WHEN date_diff('day', al.next_payment_date, CURRENT_DATE) BETWEEN 61 AND 90 THEN '61-90 days' WHEN date_diff('day', al.next_payment_date, CURRENT_DATE) BETWEEN 91 AND 120 THEN '91-120 days' WHEN date_diff('day', al.next_payment_date, CURRENT_DATE) > 120 THEN 'Over 120 days' ELSE 'CURRENT' END AS Delinquency_Bracket, COALESCE(al.delq_count_30, 0) + COALESCE(al.delq_count_60, 0) + COALESCE(al.delq_count_90, 0) + COALESCE(al.delq_count_120, 0) + COALESCE(al.delq_count_150, 0) + COALESCE(al.delq_count_180, 0) AS Total_Delinquency_Occurrences, ROUND(al.opening_balance, 2) AS Initial_Balance, ROUND(a.current_balance, 2) AS Current_Balance, ROUND(COALESCE(al.interest_ytd, 0) + COALESCE(al.interest_lytd, 0), 2) AS Total_Interest_Earned, ROUND(al.interest_ytd, 2) AS Interest_Earned_YTD, ROUND(al.interest_lytd, 2) AS Interest_Earned_LYTD, ROUND(COALESCE(al.late_fees_ytd, 0) + COALESCE(al.late_fees_lytd, 0), 2) AS Total_Late_Fees_Earned, ROUND(al.late_fees_ytd, 2) AS Late_Fees_YTD, ROUND(al.late_fees_lytd, 2) AS Late_Fees_LYTD, ROUND(COALESCE(al.interest_ytd, 0) + COALESCE(al.interest_lytd, 0) + COALESCE(al.late_fees_ytd, 0) + COALESCE(al.late_fees_lytd, 0), 2) AS Total_Revenue_Earned, CASE WHEN al.opening_balance > 0 THEN ROUND((COALESCE(al.interest_ytd, 0) + COALESCE(al.interest_lytd, 0)) / al.opening_balance * 100, 3) ELSE 0 END AS Interest_Yield_Percentage, ROUND(al.interest_rate / 12, 6) AS Monthly_Interest_Rate, CASE WHEN a.date_opened IS NOT NULL AND al.opening_balance > 0 AND al.interest_rate > 0 THEN ROUND(al.opening_balance * (al.interest_rate / 100) * date_diff('day', a.date_opened, COALESCE(a.date_closed, CURRENT_DATE)) / 365.0, 2) ELSE 0 END AS Expected_Interest_Simple, CASE WHEN a.date_opened IS NOT NULL AND al.opening_balance > 0 AND al.interest_rate > 0 THEN ROUND((COALESCE(al.interest_ytd, 0) + COALESCE(al.interest_lytd, 0)) / NULLIF(al.opening_balance * (al.interest_rate / 100) * (date_diff('day', a.date_opened, COALESCE(a.date_closed, CURRENT_DATE)) / 365.0), 0) * 100, 2) ELSE NULL END AS Interest_Performance_Ratio FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a INNER JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON a.account_id = al.account_id AND al.credit_union = '{credit_union_q}' AND a.credit_union = al.credit_union LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"account_types\" at ON UPPER((a.account_type)) = UPPER((at.account_type)) AND at.credit_union = '{credit_union_q}' AND a.credit_union = at.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = '{credit_union_q}' LEFT JOIN cu_info ci ON ci.credit_union = '{credit_union_q}' WHERE UPPER((a.discriminator)) = 'L' AND UPPER((a.account_type)) NOT IN ('CC','PCO','PCCO') AND a.credit_union = '{credit_union_q}' ORDER BY a.member_number, a.account_id ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_member_details = f"UNLOAD (SELECT fi.idfi AS idfi, a.account_id, a.account_number, COALESCE(a.description, '') AS description, a.current_balance, CASE WHEN a.date_closed IS NULL THEN 'Still Open' ELSE date_format(CAST(a.date_closed AS date), '%Y-%m-%d') END AS date_closed, a.date_opened, CASE WHEN a.date_closed IS NULL THEN 'Active' ELSE 'Closed' END AS product_status, CASE (a.discriminator) WHEN 'S' THEN 'Savings' WHEN 'D' THEN 'Checkings' WHEN 'L' THEN 'Loan' WHEN 'C' THEN 'Certificate' WHEN 'U' THEN 'Custom' END AS product_type, m.member_id, m.member_number, CASE WHEN m.member_number > 0 THEN 'Valid' ELSE 'Invalid' END AS member_number_is_valid, CASE WHEN m.inactive_flag = 'I' THEN 'Inactive Flag' ELSE 'Active Flag' END AS member_inactive_flag_status, CASE WHEN m.all_accounts_closed = 1 THEN 'All Closed' WHEN m.all_accounts_closed = 0 THEN 'Has Open Accounts' ELSE 'Unknown/NULL' END AS member_accounts_status, CASE WHEN m.member_number IS NOT NULL AND m.member_type IS NOT NULL AND m.all_accounts_closed = 0 AND m.inactive_flag <> 'I' THEN 'Active' ELSE 'Inactive' END AS member_status, m.inactive_flag AS member_inactive_flag_code, m.all_accounts_closed AS member_all_accounts_closed_flag, e.address1, date_diff('year', CAST(e.dob AS date), current_date) AS age, CASE WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 0 AND 17 THEN 'A. 0-17' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 18 AND 25 THEN 'B. 18-25' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 26 AND 35 THEN 'C. 26-35' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 36 AND 45 THEN 'D. 36-45' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 46 AND 55 THEN 'E. 46-55' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 56 AND 65 THEN 'F. 56-65' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 66 AND 75 THEN 'G. 66-75' WHEN date_diff('year', CAST(e.dob AS date), current_date) BETWEEN 76 AND 85 THEN 'H. 76-85' WHEN date_diff('year', CAST(e.dob AS date), current_date) > 85 THEN 'I. 85+' ELSE 'Unknown' END AS age_group, CASE WHEN e.name_first IS NULL OR e.name_first = '[NULL]' THEN CONCAT(UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) WHEN e.name_middle IS NOT NULL AND e.name_middle <> '[NULL]' AND e.name_middle <> '' THEN CONCAT(UPPER(substr(e.name_first, 1, 1)), LOWER(substr(e.name_first, 2)), ' ', UPPER(substr(e.name_middle, 1, 1)), LOWER(substr(e.name_middle, 2)), ' ', UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) ELSE CONCAT(UPPER(substr(e.name_first, 1, 1)), LOWER(substr(e.name_first, 2)), ' ', UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) END AS full_name, CAST(m.join_date AS date) AS join_date, CASE WHEN date_diff('day', m.join_date, current_date) < 183 THEN '1. Recent (0-6 months)' WHEN date_diff('day', m.join_date, current_date) < 365 THEN '2. New (6-12 months)' WHEN date_diff('day', m.join_date, current_date) < 1095 THEN '3. Established (1-3 years)' WHEN date_diff('day', m.join_date, current_date) < 1825 THEN '4. Mature (3-5 years)' ELSE '5. Veteran (5+ years)' END AS member_tenure_category, CASE WHEN (m.member_type) = 'P' THEN 'Personal' WHEN (m.member_type) = 'B' THEN 'Business' WHEN (m.member_type) = 'C' THEN 'Corporate Member' ELSE 'Unknown' END AS member_type, CASE WHEN m.home_bank_date IS NOT NULL THEN 'Active' ELSE 'Inactive' END AS online_banking_status FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"member\" m ON a.member_number = m.member_number LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"entity\" e ON m.member_entity_id = e.entity_id LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = '{credit_union_q}' WHERE a.account_id IS NOT NULL AND e.credit_union = '{credit_union_q}' AND m.credit_union = '{credit_union_q}' AND a.credit_union = '{credit_union_q}' ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_member_profile = f"UNLOAD (SELECT fi.idfi AS idfi, m.member_number AS member_id, CASE WHEN e.name_first IS NULL OR e.name_first = '[NULL]' THEN NULL ELSE CONCAT(UPPER(substr(e.name_first, 1, 1)), LOWER(substr(e.name_first, 2))) END AS first_name, CASE WHEN e.name_middle IS NULL OR e.name_middle = '[NULL]' THEN NULL ELSE CONCAT(UPPER(substr(e.name_middle, 1, 1)), LOWER(substr(e.name_middle, 2))) END AS middle_name, CONCAT(UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) AS last_name, e.preferred_name AS preferred_name, CASE WHEN e.name_first IS NULL OR e.name_first = '[NULL]' THEN CONCAT(UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) WHEN e.name_middle IS NOT NULL AND e.name_middle <> '[NULL]' AND e.name_middle <> '' THEN CONCAT(UPPER(substr(e.name_first, 1, 1)), LOWER(substr(e.name_first, 2)), ' ', UPPER(substr(e.name_middle, 1, 1)), LOWER(substr(e.name_middle, 2)), ' ', UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) ELSE CONCAT(UPPER(substr(e.name_first, 1, 1)), LOWER(substr(e.name_first, 2)), ' ', UPPER(substr(e.name_last, 1, 1)), LOWER(substr(e.name_last, 2))) END AS full_name, year(current_date) - year(e.dob) AS age, CASE WHEN m.inactive_flag = 'I' THEN 'Inactive' ELSE 'Active' END AS member_status_simple, CASE WHEN m.member_number > 0 THEN 'Valid' ELSE 'Invalid' END AS member_number_is_valid, CASE WHEN m.inactive_flag = 'I' THEN 'Inactive Flag' ELSE 'Active Flag' END AS member_inactive_flag_status, CASE WHEN m.all_accounts_closed = 1 THEN 'All Closed' WHEN m.all_accounts_closed = 0 THEN 'Has Open Accounts' ELSE 'Unknown/NULL' END AS member_accounts_status, CASE WHEN m.member_number IS NOT NULL AND m.member_type IS NOT NULL AND m.all_accounts_closed = 0 AND m.inactive_flag <> 'I' THEN 'Active' ELSE 'Inactive' END AS member_status, m.inactive_flag AS member_inactive_flag_code, m.all_accounts_closed AS member_all_accounts_closed_flag, CASE WHEN m.member_type = 'P' THEN 'Personal' WHEN m.member_type = 'B' THEN 'Business' WHEN m.member_type = 'C' THEN 'Corporate Member' ELSE 'Unknown' END AS member_type, DATE(m.join_date) AS join_date, year(m.join_date) AS join_year, quarter(m.join_date) AS join_quarter, month(m.join_date) AS join_month, date_diff('day', m.join_date, current_date) AS member_tenure_days, CASE WHEN date_diff('day', m.join_date, current_date) < 183 THEN '1. Recent (0-6 months)' WHEN date_diff('day', m.join_date, current_date) < 365 THEN '2. New (6-12 months)' WHEN date_diff('day', m.join_date, current_date) < 1095 THEN '3. Established (1-3 years)' WHEN date_diff('day', m.join_date, current_date) < 1825 THEN '4. Mature (3-5 years)' ELSE '5. Veteran (5+ years)' END AS member_tenure_category, CASE WHEN e.gender = 'F' THEN 'Female' WHEN e.gender = 'M' THEN 'Male' WHEN e.gender = 'N' THEN 'Non-Binary' WHEN e.gender = 'O' THEN 'Opt Out' ELSE 'Unknown' END AS gender, CASE WHEN year(current_date) - year(e.dob) BETWEEN 0 AND 17 THEN '0-17' WHEN year(current_date) - year(e.dob) BETWEEN 18 AND 25 THEN '18-25' WHEN year(current_date) - year(e.dob) BETWEEN 26 AND 35 THEN '26-35' WHEN year(current_date) - year(e.dob) BETWEEN 36 AND 45 THEN '36-45' WHEN year(current_date) - year(e.dob) BETWEEN 46 AND 55 THEN '46-55' WHEN year(current_date) - year(e.dob) BETWEEN 56 AND 65 THEN '56-65' WHEN year(current_date) - year(e.dob) BETWEEN 66 AND 75 THEN '66-75' WHEN year(current_date) - year(e.dob) BETWEEN 76 AND 85 THEN '76-85' WHEN year(current_date) - year(e.dob) > 85 THEN '85+' ELSE 'Unknown' END AS age_group, year(current_date) - year(e.dob) AS calculated_age, CASE WHEN e.foreign_address = 1 THEN UPPER(e.physical_address1) ELSE UPPER(e.address1) END AS address1, CASE WHEN e.foreign_address = 1 THEN UPPER(e.physical_address2) ELSE UPPER(e.address2) END AS address2, CASE WHEN e.foreign_address = 1 THEN COALESCE(UPPER(e.physical_city), 'Unknown') ELSE COALESCE(UPPER(e.city), 'Unknown') END AS city, CASE WHEN e.foreign_address = 1 THEN COALESCE(UPPER(e.physical_state), 'Unknown') ELSE COALESCE(UPPER(e.state), 'Unknown') END AS state, CASE WHEN e.foreign_address = 1 THEN COALESCE(UPPER(e.physical_zip), 'Unknown') ELSE COALESCE(UPPER(e.zip), 'Unknown') END AS zip_code, CASE WHEN e.foreign_address = 1 THEN COALESCE(UPPER(e.physical_country), 'Unknown') ELSE COALESCE(UPPER(e.country), 'Unknown') END AS country, CASE WHEN e.foreign_address = 1 THEN CONCAT(COALESCE(UPPER(e.physical_city), 'Unknown'), ', ', COALESCE(UPPER(e.physical_state), 'Unknown')) ELSE CONCAT(COALESCE(UPPER(e.city), 'Unknown'), ', ', COALESCE(UPPER(e.state), 'Unknown')) END AS city_state, CASE WHEN e.foreign_address = 1 THEN 'Physical' ELSE 'Mailing' END AS address_type_used, m.branch_number AS branch, COALESCE(eg.description, 'Unknown') AS eligibility_group, CASE WHEN m.home_bank_date IS NOT NULL THEN 'Active' ELSE 'Inactive' END AS online_banking_status, CASE WHEN m.last_nondiv_activity >= date_add('day', -30, current_date) THEN 'Active' WHEN m.last_nondiv_activity IS NOT NULL THEN 'Inactive' ELSE 'Unknown' END AS activity_30_days, CASE WHEN m.last_nondiv_activity >= date_add('day', -90, current_date) THEN 'Active' WHEN m.last_nondiv_activity IS NOT NULL THEN 'Inactive' ELSE 'Unknown' END AS activity_90_days, COALESCE(account_summary.total_account_count, 0) AS total_account_count, COALESCE(account_summary.share_count, 0) AS savings_accounts_count, COALESCE(account_summary.draft_count, 0) AS checking_accounts_count, COALESCE(account_summary.loan_count, 0) AS loan_accounts_count, COALESCE(account_summary.cert_count, 0) AS certificate_accounts_count, CASE WHEN COALESCE(account_summary.share_count, 0) > 0 THEN 1 ELSE 0 END AS has_savings, CASE WHEN COALESCE(account_summary.draft_count, 0) > 0 THEN 1 ELSE 0 END AS has_checking, CASE WHEN COALESCE(account_summary.loan_count, 0) > 0 THEN 1 ELSE 0 END AS has_loans, CASE WHEN COALESCE(account_summary.cert_count, 0) > 0 THEN 1 ELSE 0 END AS has_certificates, (CASE WHEN COALESCE(account_summary.share_count, 0) > 0 THEN 1 ELSE 0 END + CASE WHEN COALESCE(account_summary.draft_count, 0) > 0 THEN 1 ELSE 0 END + CASE WHEN COALESCE(account_summary.loan_count, 0) > 0 THEN 1 ELSE 0 END + CASE WHEN COALESCE(account_summary.cert_count, 0) > 0 THEN 1 ELSE 0 END) AS distinct_product_types_count, (COALESCE(account_summary.share_count, 0) + COALESCE(account_summary.draft_count, 0) + COALESCE(account_summary.loan_count, 0) + COALESCE(account_summary.cert_count, 0)) AS total_products_by_type, CASE WHEN COALESCE(account_summary.total_account_count, 0) = 0 THEN 'No Products' WHEN ((CASE WHEN COALESCE(account_summary.share_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.draft_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.loan_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.cert_count, 0) > 0 THEN 1 ELSE 0 END)) = 1 THEN 'Single Product' WHEN ((CASE WHEN COALESCE(account_summary.share_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.draft_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.loan_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.cert_count, 0) > 0 THEN 1 ELSE 0 END)) = 4 THEN 'Full Relationship' WHEN ((CASE WHEN COALESCE(account_summary.share_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.draft_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.loan_count, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(account_summary.cert_count, 0) > 0 THEN 1 ELSE 0 END)) BETWEEN 2 AND 3 THEN 'Multi Product' ELSE 'Unknown' END AS product_relationship_category, (CASE WHEN m.home_bank_date IS NOT NULL THEN 40 ELSE 0 END + CASE WHEN m.last_nondiv_activity >= date_add('day', -30, current_date) THEN 30 ELSE 0 END + CASE WHEN m.last_nondiv_activity >= date_add('day', -90, current_date) THEN 20 ELSE 0 END + CASE WHEN COALESCE(account_summary.total_account_count, 0) > 1 THEN 10 ELSE 0 END) AS engagement_score, m.last_nondiv_activity AS last_activity_date, m.home_bank_date AS last_online_banking_date, CASE WHEN m.all_accounts_closed = 1 THEN 'Yes' ELSE 'No' END AS all_accounts_closed, attrition_data.latest_account_closure_date AS attrition_date, CASE WHEN m.all_accounts_closed = 1 AND attrition_data.latest_account_closure_date IS NOT NULL THEN date_diff('day', m.join_date, attrition_data.latest_account_closure_date) ELSE NULL END AS member_lifespan_days, CASE WHEN m.all_accounts_closed = 1 AND attrition_data.latest_account_closure_date IS NOT NULL THEN CASE WHEN date_diff('day', m.join_date, attrition_data.latest_account_closure_date) < 90 THEN 'Early (0-3 months)' WHEN date_diff('day', m.join_date, attrition_data.latest_account_closure_date) < 365 THEN 'Short (3-12 months)' WHEN date_diff('day', m.join_date, attrition_data.latest_account_closure_date) < 1095 THEN 'Medium (1-3 years)' WHEN date_diff('day', m.join_date, attrition_data.latest_account_closure_date) < 1825 THEN 'Long (3-5 years)' ELSE 'Very Long (5+ years)' END ELSE NULL END AS attrition_category, current_date AS data_extract_date FROM \"AwsDataCatalog\".\"silver_know\".\"member\" m LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"entity\" e ON m.member_entity_id = e.entity_id AND m.credit_union = e.credit_union AND e.credit_union = '{credit_union_q}' LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"eligibility_group\" eg ON m.eligibility_group_id = eg.eligibility_group_id AND eg.credit_union = '{credit_union_q}' LEFT JOIN ( SELECT credit_union, member_number, COUNT(DISTINCT account_id) AS total_account_count, COUNT(DISTINCT CASE WHEN discriminator = 'S' THEN account_id END) AS share_count, COUNT(DISTINCT CASE WHEN discriminator = 'D' THEN account_id END) AS draft_count, COUNT(DISTINCT CASE WHEN discriminator = 'L' THEN account_id END) AS loan_count, COUNT(DISTINCT CASE WHEN discriminator = 'C' THEN account_id END) AS cert_count FROM \"AwsDataCatalog\".\"silver_know\".\"account\" WHERE date_closed IS NULL AND credit_union = '{credit_union_q}' GROUP BY credit_union, member_number ) account_summary ON m.member_number = account_summary.member_number LEFT JOIN ( SELECT a.credit_union, a.member_number, MAX(a.date_closed) AS latest_account_closure_date FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a INNER JOIN \"AwsDataCatalog\".\"silver_know\".\"member\" m2 ON a.member_number = m2.member_number WHERE a.credit_union = '{credit_union_q}' AND a.date_closed IS NOT NULL AND m2.credit_union = '{credit_union_q}' AND m2.all_accounts_closed = 1 GROUP BY a.credit_union, a.member_number ) attrition_data ON m.member_number = attrition_data.member_number AND m.credit_union = attrition_data.credit_union LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = '{credit_union_q}' WHERE m.credit_union = '{credit_union_q}' AND m.member_number IS NOT NULL AND m.member_type IS NOT NULL ORDER BY m.member_number ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_member_transactions = f"UNLOAD (SELECT fi.idfi AS idfi, a.member_number, COUNT(*) AS total_transactions_lifetime, ROUND(SUM(ABS(th.total_amount)), 2) AS total_transaction_amount_lifetime, ROUND(AVG(ABS(th.total_amount)), 2) AS avg_transaction_amount_lifetime, COUNT(CASE WHEN th.total_amount < 0 THEN 1 END) AS debit_transactions_lifetime, COUNT(CASE WHEN th.total_amount > 0 THEN 1 END) AS credit_transactions_lifetime, ROUND(SUM(CASE WHEN th.total_amount < 0 THEN ABS(th.total_amount) ELSE 0 END), 2) AS debit_amount_lifetime, ROUND(SUM(CASE WHEN th.total_amount > 0 THEN th.total_amount ELSE 0 END), 2) AS credit_amount_lifetime, COUNT(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) THEN 1 END) AS total_transactions_mtd, ROUND(SUM(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) THEN ABS(th.total_amount) ELSE 0 END), 2) AS total_transaction_amount_mtd, ROUND(AVG(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) THEN ABS(th.total_amount) END), 2) AS avg_transaction_amount_mtd, COUNT(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) AND th.total_amount < 0 THEN 1 END) AS debit_transactions_mtd, COUNT(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) AND th.total_amount > 0 THEN 1 END) AS credit_transactions_mtd, ROUND(SUM(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) AND th.total_amount < 0 THEN ABS(th.total_amount) ELSE 0 END), 2) AS debit_amount_mtd, ROUND(SUM(CASE WHEN year(th.date_effective) = year(current_date) AND month(th.date_effective) = month(current_date) AND th.total_amount > 0 THEN th.total_amount ELSE 0 END), 2) AS credit_amount_mtd, COUNT(CASE WHEN th.date_effective >= date_add('day', -30, current_date) THEN 1 END) AS total_transactions_30d, ROUND(SUM(CASE WHEN th.date_effective >= date_add('day', -30, current_date) THEN ABS(th.total_amount) ELSE 0 END), 2) AS total_transaction_amount_30d, ROUND(AVG(CASE WHEN th.date_effective >= date_add('day', -30, current_date) THEN ABS(th.total_amount) END), 2) AS avg_transaction_amount_30d, COUNT(CASE WHEN th.date_effective >= date_add('day', -30, current_date) AND th.total_amount < 0 THEN 1 END) AS debit_transactions_30d, COUNT(CASE WHEN th.date_effective >= date_add('day', -30, current_date) AND th.total_amount > 0 THEN 1 END) AS credit_transactions_30d, ROUND(SUM(CASE WHEN th.date_effective >= date_add('day', -30, current_date) AND th.total_amount < 0 THEN ABS(th.total_amount) ELSE 0 END), 2) AS debit_amount_30d, ROUND(SUM(CASE WHEN th.date_effective >= date_add('day', -30, current_date) AND th.total_amount > 0 THEN th.total_amount ELSE 0 END), 2) AS credit_amount_30d, COUNT(CASE WHEN th.date_effective >= date_add('day', -90, current_date) THEN 1 END) AS total_transactions_90d, ROUND(SUM(CASE WHEN th.date_effective >= date_add('day', -90, current_date) THEN ABS(th.total_amount) ELSE 0 END), 2) AS total_transaction_amount_90d, ROUND(AVG(CASE WHEN th.date_effective >= date_add('day', -90, current_date) THEN ABS(th.total_amount) END), 2) AS avg_transaction_amount_90d, COUNT(CASE WHEN th.date_effective >= date_add('day', -90, current_date) AND th.total_amount < 0 THEN 1 END) AS debit_transactions_90d, COUNT(CASE WHEN th.date_effective >= date_add('day', -90, current_date) AND th.total_amount > 0 THEN 1 END) AS credit_transactions_90d, ROUND(SUM(CASE WHEN th.date_effective >= date_add('day', -90, current_date) AND th.total_amount < 0 THEN ABS(th.total_amount) ELSE 0 END), 2) AS debit_amount_90d, ROUND(SUM(CASE WHEN th.date_effective >= date_add('day', -90, current_date) AND th.total_amount > 0 THEN th.total_amount ELSE 0 END), 2) AS credit_amount_90d, COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN 1 END) AS total_transactions_12m, ROUND(SUM(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN ABS(th.total_amount) ELSE 0 END), 2) AS total_transaction_amount_12m, ROUND(AVG(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN ABS(th.total_amount) END), 2) AS avg_transaction_amount_12m, COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) AND COALESCE(TRY_CAST(at2.credit_card AS integer), 0) = 1 THEN 1 END) AS debit_transactions_12m, COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) AND th.total_amount > 0 THEN 1 END) AS credit_transactions_12m, ROUND(SUM(CASE WHEN th.date_effective >= date_add('month', -12, current_date) AND th.total_amount < 0 THEN ABS(th.total_amount) ELSE 0 END), 2) AS debit_amount_12m, ROUND(SUM(CASE WHEN th.date_effective >= date_add('month', -12, current_date) AND th.total_amount > 0 THEN th.total_amount ELSE 0 END), 2) AS credit_amount_12m, COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) AND COALESCE(TRY_CAST(at2.credit_card AS integer), 0) = 1 THEN 1 END) AS credit_card_transactions_12m, ROUND(SUM(CASE WHEN th.date_effective >= date_add('month', -12, current_date) AND COALESCE(TRY_CAST(at2.credit_card AS integer), 0) = 1 THEN ABS(th.total_amount) ELSE 0 END), 2) AS credit_card_amount_12m, CASE WHEN COUNT(CASE WHEN th.date_effective >= date_add('day', -30, current_date) THEN 1 END) > 0 THEN 'Active' ELSE 'Inactive' END AS transaction_activity_30d, CASE WHEN COUNT(CASE WHEN th.date_effective >= date_add('day', -90, current_date) THEN 1 END) > 0 THEN 'Active' ELSE 'Inactive' END AS transaction_activity_90d, CASE WHEN COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN 1 END) = 0 THEN 'No Transactions' WHEN COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN 1 END) <= 12 THEN 'Low Volume (≤12/year)' WHEN COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN 1 END) <= 52 THEN 'Medium Volume (13-52/year)' WHEN COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN 1 END) <= 156 THEN 'High Volume (53-156/year)' ELSE 'Very High Volume (>156/year)' END AS transaction_volume_category, CASE WHEN COUNT(CASE WHEN th.date_effective >= date_add('day', -30, current_date) THEN 1 END) > 0 THEN 20 ELSE 0 END AS transaction_score_30d, CASE WHEN COUNT(CASE WHEN th.date_effective >= date_add('day', -30, current_date) THEN 1 END) > 5 THEN 10 ELSE 0 END AS transaction_score_volume, CASE WHEN COUNT(CASE WHEN th.date_effective >= date_add('month', -12, current_date) THEN 1 END) > 52 THEN 20 ELSE 0 END AS transaction_score_annual, MIN(th.date_effective) AS first_transaction_date, MAX(th.date_effective) AS last_transaction_date, CASE WHEN MAX(th.date_effective) IS NOT NULL THEN date_diff('day', MAX(th.date_effective), current_date) ELSE NULL END AS days_since_last_transaction, current_date AS transaction_data_extract_date FROM \"AwsDataCatalog\".\"silver_know\".\"transaction_history\" th INNER JOIN \"AwsDataCatalog\".\"silver_know\".\"account\" a ON a.account_id = th.account_id LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"account_types\" at2 ON a.account_type = at2.account_type LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON fi.prodigy_code = '{credit_union_q}' WHERE a.member_number IS NOT NULL AND a.credit_union = '{credit_union_q}' AND th.credit_union = '{credit_union_q}' AND at2.credit_union = '{credit_union_q}' GROUP BY fi.idfi, a.member_number ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_products_overview = f"UNLOAD (WITH member_product_counts AS ( SELECT credit_union, member_number, COUNT(*) AS total_products_per_member FROM ( SELECT a.credit_union, a.member_number FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a WHERE a.member_number > 0 AND a.credit_union = '{credit_union_q}' AND UPPER(a.discriminator) IN ('S','D','C','U') AND a.date_closed IS NULL AND UPPER(COALESCE(a.access_control, '')) NOT IN ('B','R') UNION ALL SELECT a.credit_union, a.member_number FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON a.account_id = al.account_id AND al.credit_union = '{credit_union_q}' AND a.credit_union = al.credit_union WHERE a.member_number > 0 AND a.credit_union = '{credit_union_q}' AND UPPER(a.discriminator) = 'L' AND UPPER(a.account_type) NOT IN ('CC','PCO','PCCO') AND a.date_closed IS NULL AND a.charge_off_date IS NULL UNION ALL SELECT c.credit_union, c.member_number FROM \"AwsDataCatalog\".\"silver_know\".\"eft_card_file\" c WHERE c.member_number > 0 AND c.credit_union = '{credit_union_q}' AND UPPER(c.card_type) IN ('D','DI','A') AND c.block_date IS NULL AND c.expire_date >= current_date AND CAST(c.reject_code AS varchar) NOT IN ('34','36','41','43','07') AND CAST(c.lost_or_stolen AS varchar) = ' ' AND c.last_pin_used_date IS NOT NULL UNION ALL SELECT c.credit_union, c.member_number FROM \"AwsDataCatalog\".\"silver_know\".\"eft_card_file\" c WHERE c.member_number > 0 AND c.credit_union = '{credit_union_q}' AND UPPER(c.card_type) IN ('C','PC') AND c.block_date IS NULL AND c.expire_date >= current_date AND CAST(c.reject_code AS varchar) NOT IN ('34','36','41','43','07') AND CAST(c.lost_or_stolen AS varchar) = ' ' AND c.last_pin_used_date IS NOT NULL UNION ALL SELECT a.credit_union, a.member_number FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON a.account_id = al.account_id AND al.credit_union = '{credit_union_q}' AND a.credit_union = al.credit_union WHERE a.member_number > 0 AND a.credit_union = '{credit_union_q}' AND UPPER(a.discriminator) = 'L' AND al.credit_limit > 0 AND a.date_closed IS NULL AND a.charge_off_date IS NULL ) all_products GROUP BY credit_union, member_number ), cu_info AS ( SELECT DISTINCT cui.credit_union, cui.credit_union_name, fi.idfi FROM \"AwsDataCatalog\".\"silver_know\".\"credit_union_info\" cui LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(fi.prodigy_code) = '{credit_union_q}' WHERE cui.credit_union = '{credit_union_q}' ), member_status AS ( SELECT m.credit_union, m.member_number, CASE WHEN m.member_number IS NOT NULL AND m.member_type IS NOT NULL AND m.all_accounts_closed = 0 AND m.inactive_flag <> 'I' THEN 'Active' ELSE 'Inactive' END AS member_status, CASE WHEN m.member_number > 0 THEN 'Valid' ELSE 'Invalid' END AS member_number_is_valid, CASE WHEN m.inactive_flag = 'I' THEN 'Inactive Flag' ELSE 'Active Flag' END AS member_inactive_flag_status, CASE WHEN m.all_accounts_closed = 1 THEN 'All Closed' WHEN m.all_accounts_closed = 0 THEN 'Has Open Accounts' ELSE 'Unknown/NULL' END AS member_accounts_status, m.inactive_flag AS member_inactive_flag_code, m.all_accounts_closed AS member_all_accounts_closed_flag FROM \"AwsDataCatalog\".\"silver_know\".\"member\" m WHERE m.credit_union = '{credit_union_q}' ), member_kind AS ( SELECT m.credit_union, m.member_number, CASE WHEN m.member_type = 'B' THEN 'Business' WHEN m.member_type = 'C' THEN 'Corporate' WHEN m.member_type = 'P' THEN 'Member' ELSE 'Unknown' END AS member_category FROM \"AwsDataCatalog\".\"silver_know\".\"member\" m WHERE m.member_number > 0 AND m.credit_union = '{credit_union_q}' ), recent_account_activity AS ( SELECT DISTINCT th.credit_union, th.account_id FROM \"AwsDataCatalog\".\"silver_know\".\"transaction_history\" th WHERE th.date_actual >= date_add('day', -90,current_date) AND th.void_flag = 0 AND th.credit_union = '{credit_union_q}' ) SELECT ci.idfi AS idfi, a.member_number AS id_member, a.account_number AS id_product, 'Accounts' AS main_category, CASE WHEN UPPER(a.discriminator) = 'S' THEN 'Savings Account' WHEN UPPER(a.discriminator) = 'D' THEN 'Checking Account' WHEN UPPER(a.discriminator) = 'C' THEN 'Certificate Account' WHEN UPPER(a.discriminator) = 'U' THEN 'Other Account' END AS category_product, ci.credit_union_name AS cu_name, a.account_number AS product_number, a.date_opened AS date_opened_product, a.date_closed AS date_closed_product, mpc.total_products_per_member AS number_of_products_for_member, CASE WHEN a.date_closed IS NULL THEN 'Active' ELSE 'Inactive' END AS product_is_active, CASE WHEN ra.account_id IS NOT NULL THEN 'With Recent Activity' ELSE 'No Recent Activity' END AS recent_activity_status, ms.member_status AS member_status, 'account' AS table_name_origin, mk.member_category, ms.member_number_is_valid, ms.member_inactive_flag_status, ms.member_accounts_status, ms.member_inactive_flag_code, ms.member_all_accounts_closed_flag, concat('{credit_union_q}','_',CAST(a.member_number AS varchar),'_',CAST(a.account_number AS varchar)) AS record_key FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a JOIN cu_info ci ON ci.credit_union = a.credit_union LEFT JOIN member_product_counts mpc ON mpc.credit_union = a.credit_union AND mpc.member_number = a.member_number LEFT JOIN member_status ms ON ms.credit_union = a.credit_union AND ms.member_number = a.member_number LEFT JOIN member_kind mk ON mk.credit_union = a.credit_union AND mk.member_number = a.member_number LEFT JOIN recent_account_activity ra ON ra.credit_union = a.credit_union AND ra.account_id = a.account_id WHERE a.member_number > 0 AND a.credit_union = '{credit_union_q}' AND UPPER(a.discriminator) IN ('S','D','C','U') UNION ALL SELECT  ci.idfi AS idfi, a.member_number AS id_member, a.account_number AS id_product, 'Loans' AS main_category, 'Loan' AS category_product, ci.credit_union_name AS cu_name, a.account_number AS product_number, a.date_opened AS date_opened_product, a.date_closed AS date_closed_product, mpc.total_products_per_member AS number_of_products_for_member, CASE WHEN a.date_closed IS NULL AND a.charge_off_date IS NULL THEN 'Active' ELSE 'Inactive' END AS product_is_active, CASE WHEN ra.account_id IS NOT NULL THEN 'With Recent Activity' ELSE 'No Recent Activity' END AS recent_activity_status, ms.member_status AS member_status, 'account_loan' AS table_name_origin, mk.member_category, ms.member_number_is_valid, ms.member_inactive_flag_status, ms.member_accounts_status, ms.member_inactive_flag_code, ms.member_all_accounts_closed_flag, concat('{credit_union_q}','_',CAST(a.member_number AS varchar),'_',CAST(a.account_number AS varchar)) AS record_key FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON a.account_id = al.account_id AND al.credit_union = '{credit_union_q}' AND a.credit_union = al.credit_union JOIN cu_info ci ON ci.credit_union = a.credit_union LEFT JOIN member_product_counts mpc ON mpc.credit_union = a.credit_union AND mpc.member_number = a.member_number LEFT JOIN member_status ms ON ms.credit_union = a.credit_union AND ms.member_number = a.member_number LEFT JOIN member_kind mk ON mk.credit_union = a.credit_union AND mk.member_number = a.member_number LEFT JOIN recent_account_activity ra ON ra.credit_union = a.credit_union AND ra.account_id = a.account_id WHERE a.member_number > 0 AND a.credit_union = '{credit_union_q}' AND UPPER(a.discriminator) = 'L' AND UPPER(a.account_type) NOT IN ('CC','PCO','PCCO') UNION ALL SELECT  ci.idfi AS idfi, c.member_number AS id_member, concat(CAST(c.member_number AS varchar),'_CARD_',CAST(c.record_number AS varchar)) AS id_product, 'Cards' AS main_category, CASE WHEN UPPER(c.card_type) = 'D' THEN 'Debit Card' WHEN UPPER(c.card_type) = 'DI' THEN 'Debit Instant Card' WHEN UPPER(c.card_type) = 'A' THEN 'ATM Card' ELSE 'Other Debit Card' END AS category_product, ci.credit_union_name AS cu_name, CAST(c.record_number AS varchar) AS product_number, c.issue_date AS date_opened_product, CASE WHEN c.block_date IS NOT NULL THEN c.block_date WHEN c.expire_date < current_date THEN c.expire_date ELSE NULL END AS date_closed_product, mpc.total_products_per_member AS number_of_products_for_member, CASE WHEN c.block_date IS NULL AND c.expire_date >= current_date AND CAST(c.reject_code AS varchar) = '00' AND CAST(c.lost_or_stolen AS varchar) = ' ' AND c.last_pin_used_date IS NOT NULL THEN 'Active' ELSE 'Inactive' END AS product_is_active, CASE WHEN c.last_pin_used_date >= date_add('day',-90,current_date) THEN 'With Recent Activity' ELSE 'No Recent Activity' END AS recent_activity_status, ms.member_status AS member_status, 'eft_card_file_debit' AS table_name_origin, mk.member_category, ms.member_number_is_valid, ms.member_inactive_flag_status, ms.member_accounts_status, ms.member_inactive_flag_code, ms.member_all_accounts_closed_flag, concat('{credit_union_q}','_',CAST(c.member_number AS varchar),'_',CAST(c.record_number AS varchar)) AS record_key FROM \"AwsDataCatalog\".\"silver_know\".\"eft_card_file\" c JOIN cu_info ci ON ci.credit_union = c.credit_union LEFT JOIN member_product_counts mpc ON mpc.credit_union = c.credit_union AND mpc.member_number = c.member_number LEFT JOIN member_status ms ON ms.credit_union = c.credit_union AND ms.member_number = c.member_number LEFT JOIN member_kind mk ON mk.credit_union = c.credit_union AND mk.member_number = c.member_number WHERE c.member_number > 0 AND UPPER(c.card_type) IN ('D','DI','A') AND c.credit_union = '{credit_union_q}' UNION ALL SELECT ci.idfi AS idfi, c.member_number AS id_member, concat(CAST(c.member_number AS varchar),'_CREDITCARD_',CAST(c.record_number AS varchar)) AS id_product, 'Cards' AS main_category, CASE WHEN UPPER(c.card_type) = 'C' THEN 'Credit Gold Card' WHEN UPPER(c.card_type) = 'PC' THEN 'Credit Platinum Card' ELSE 'Other Credit Card' END AS category_product, ci.credit_union_name AS cu_name, CAST(c.record_number AS varchar) AS product_number, c.issue_date AS date_opened_product, CASE WHEN c.block_date IS NOT NULL THEN c.block_date WHEN c.expire_date < current_date THEN c.expire_date ELSE NULL END AS date_closed_product, mpc.total_products_per_member AS number_of_products_for_member, CASE WHEN c.block_date IS NULL AND c.expire_date >= current_date AND CAST(c.reject_code AS varchar) = '00' AND CAST(c.lost_or_stolen AS varchar) = ' ' AND c.last_pin_used_date IS NOT NULL THEN 'Active' ELSE 'Inactive' END AS product_is_active, CASE WHEN c.last_pin_used_date >= date_add('day',-90,current_date) THEN 'With Recent Activity' ELSE 'No Recent Activity' END AS recent_activity_status, ms.member_status AS member_status, 'eft_card_file_credit' AS table_name_origin, mk.member_category, ms.member_number_is_valid, ms.member_inactive_flag_status, ms.member_accounts_status, ms.member_inactive_flag_code, ms.member_all_accounts_closed_flag, concat('{credit_union_q}','_',CAST(c.member_number AS varchar),'_',CAST(c.record_number AS varchar)) AS record_key FROM \"AwsDataCatalog\".\"silver_know\".\"eft_card_file\" c JOIN cu_info ci ON ci.credit_union = c.credit_union LEFT JOIN member_product_counts mpc ON mpc.credit_union = c.credit_union AND mpc.member_number = c.member_number LEFT JOIN member_status ms ON ms.credit_union = c.credit_union AND ms.member_number = c.member_number LEFT JOIN member_kind mk ON mk.credit_union = c.credit_union AND mk.member_number = c.member_number WHERE c.member_number > 0 AND UPPER(c.card_type) IN ('C','PC') AND c.credit_union = '{credit_union_q}' UNION ALL SELECT ci.idfi AS idfi, a.member_number AS id_member, concat(CAST(a.account_number AS varchar),'_CREDIT_ACCOUNT') AS id_product, 'Cards' AS main_category, 'Credit Card Account' AS category_product, ci.credit_union_name AS cu_name, a.account_number AS product_number, a.date_opened AS date_opened_product, a.date_closed AS date_closed_product, mpc.total_products_per_member AS number_of_products_for_member, CASE WHEN a.date_closed IS NULL AND a.charge_off_date IS NULL THEN 'Active' ELSE 'Inactive' END AS product_is_active, CASE WHEN ra.account_id IS NOT NULL THEN 'With Recent Activity' ELSE 'No Recent Activity' END AS recent_activity_status, ms.member_status AS member_status, 'account_loan_credit' AS table_name_origin, mk.member_category, ms.member_number_is_valid, ms.member_inactive_flag_status, ms.member_accounts_status, ms.member_inactive_flag_code, ms.member_all_accounts_closed_flag, concat('{credit_union_q}','_',CAST(a.member_number AS varchar),'_',a.account_number) AS record_key FROM \"AwsDataCatalog\".\"silver_know\".\"account\" a JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON a.account_id = al.account_id AND al.credit_union = '{credit_union_q}' AND a.credit_union = al.credit_union JOIN cu_info ci ON ci.credit_union = a.credit_union LEFT JOIN member_product_counts mpc ON mpc.credit_union = a.credit_union AND mpc.member_number = a.member_number LEFT JOIN member_status ms ON ms.credit_union = a.credit_union AND ms.member_number = a.member_number LEFT JOIN member_kind mk ON mk.credit_union = a.credit_union AND mk.member_number = a.member_number LEFT JOIN recent_account_activity ra ON ra.credit_union = a.credit_union AND ra.account_id = a.account_id WHERE a.member_number > 0 AND UPPER(a.discriminator) = 'L' AND al.credit_limit > 0 AND a.credit_union = '{credit_union_q}' ) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_delinquency_history = f"UNLOAD (WITH l_month_end AS (SELECT l.credit_union, l.account_id, l.record_date FROM \"AwsDataCatalog\".\"silver_know\".\"eom_loan\" l WHERE l.credit_union = '{credit_union_q}' AND CAST(l.record_date AS date) >= date_add('month', -11, last_day_of_month(date_add('month', -1, current_date))) AND CAST(l.record_date AS date) <= last_day_of_month(date_add('month', -1, current_date)) AND CAST(l.record_date AS date) = last_day_of_month(CAST(l.record_date AS date)) AND l.date_closed IS NULL AND l.balance > 0), skip_agg AS (SELECT lm.credit_union, lm.account_id, lm.record_date, SUM(CASE WHEN lsp.payment_to_skip <= lm.record_date THEN 1 ELSE 0 END) AS total_skip_payments_raw, SUM(CASE WHEN lsp.payment_to_skip <= lm.record_date THEN COALESCE(lsp.fee_amount, 0) ELSE 0 END) AS total_skip_fees_raw, MAX(CASE WHEN lsp.payment_to_skip <= lm.record_date THEN lsp.payment_to_skip END) AS last_skip_payment_date, MAX(CASE WHEN lsp.skip_completed = 0 AND lsp.payment_to_skip >= lm.record_date THEN 1 ELSE 0 END) AS has_active_skip_payment, MAX(CASE WHEN lsp.payment_to_skip >= date_add('month', -3, lm.record_date) AND lsp.payment_to_skip <= lm.record_date THEN 1 ELSE 0 END) AS has_recent_skip_payment, MAX(CASE WHEN lsp.payment_to_skip >= date_add('month', -3, lm.record_date) AND lsp.payment_to_skip <= lm.record_date THEN lsp.payment_to_skip END) AS recent_skip_payment_date FROM l_month_end lm LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"loan_skip_payment\" lsp ON lsp.account_id = lm.account_id AND lsp.credit_union = lm.credit_union GROUP BY lm.credit_union, lm.account_id, lm.record_date), monthly_data AS (SELECT a.credit_union, concat(date_format(l.record_date, '%Y-%m'), '-', cast(l.account_id AS varchar)) AS id_general, date_format(l.record_date, '%Y-%m') AS period, l.record_date AS date, a.account_number AS loan_account_number, l.account_id AS loan_id, a.date_opened AS date_loan_opened, l.balance AS loan_balance, l.balance / SUM(l.balance) OVER (PARTITION BY date_format(l.record_date, '%Y-%m')) AS loan_balance_pct_month, CASE WHEN date_diff('day', l.next_payment_date, l.record_date) > 0 THEN l.balance / NULLIF(SUM(CASE WHEN date_diff('day', l.next_payment_date, l.record_date) > 0 THEN l.balance ELSE 0 END) OVER (PARTITION BY date_format(l.record_date, '%Y-%m')), 0) ELSE NULL END AS loan_balance_pct_delinquent, t.cb_loan_type, CASE WHEN t.cb_loan_type = '00' THEN 'Auto Loans' WHEN t.cb_loan_type = '01' THEN 'Unsecured/Personal Loans' WHEN t.cb_loan_type = '02' THEN 'Share/CD Secured Loans' WHEN t.cb_loan_type = '03' THEN 'Signature Secured Loans' WHEN t.cb_loan_type = '11' THEN 'Recreational Vehicle Loans' WHEN t.cb_loan_type = '15' THEN 'Overdraft Protection' WHEN t.cb_loan_type = '18' THEN 'Credit Card' WHEN t.cb_loan_type = '26' THEN 'Real Estate/Mortgage Loans' WHEN t.cb_loan_type = '89' THEN 'Home Equity Loans' ELSE 'Unclassified' END AS loan_main_category, al.number_of_payments AS loan_months_term, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 1 ELSE 0 END AS missed_first_payment_flag, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 'Missed First Payment (Overdue)' WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) = 0 THEN 'Due Today (Not Paid Yet)' WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) < 0 THEN 'No Payment Yet (Not Due)' WHEN al.last_payment_date IS NOT NULL THEN 'Has Made Payment(s)' ELSE 'Unknown' END AS first_payment_status, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN date_diff('day', l.next_payment_date, l.record_date) ELSE NULL END AS days_overdue_first_payment, al.last_payment_date AS last_payment_date, CASE WHEN date_diff('day', l.next_payment_date, l.record_date) < 0 THEN 0 ELSE date_diff('day', l.next_payment_date, l.record_date) END AS days_delinquency, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 'First Payment Delinquency' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 1 AND 30 THEN '1-30 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 31 AND 60 THEN '31-60 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 61 AND 90 THEN '61-90 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 91 AND 120 THEN '91-120 days' WHEN date_diff('day', l.next_payment_date, l.record_date) > 120 THEN 'Over 120 days' ELSE '0 days' END AS bracket_delinquency, (coalesce(array_position(ARRAY['0 days','First Payment Delinquency','1-30 days','31-60 days','61-90 days','91-120 days','Over 120 days'], CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 'First Payment Delinquency' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 1 AND 30 THEN '1-30 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 31 AND 60 THEN '31-60 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 61 AND 90 THEN '61-90 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 91 AND 120 THEN '91-120 days' WHEN date_diff('day', l.next_payment_date, l.record_date) > 120 THEN 'Over 120 days' ELSE '0 days' END), 0) - 1) AS current_rank, al.credit_score AS credit_score, l.next_payment_date AS next_payment_date, m.member_entity_id AS member_id, a.member_number AS member_number, pn.phone_number AS member_phone, e.email1 AS member_email, CASE WHEN e.gender = 'M' THEN 'Male' WHEN e.gender = 'F' THEN 'Female' WHEN e.gender = 'O' THEN 'Other' WHEN e.gender = '' OR e.gender IS NULL THEN 'Unknown' ELSE 'Other' END AS member_gender, CASE WHEN e.dob IS NULL THEN 'Age Unknown' WHEN date_diff('year', e.dob, l.record_date) < 25 THEN 'Under 25' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 25 AND 34 THEN '25-34 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 35 AND 44 THEN '35-44 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 45 AND 54 THEN '45-54 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 55 AND 64 THEN '55-64 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 65 AND 74 THEN '65-74 years' WHEN date_diff('year', e.dob, l.record_date) >= 75 THEN '75+ years' ELSE 'Age Unknown' END AS member_age_category, CASE WHEN m.join_date IS NULL THEN 'Unknown Tenure' WHEN date_diff('year', m.join_date, l.record_date) < 1 THEN 'New Member (<1 year)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 1 AND 2 THEN 'Recent Member (1-2 years)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 3 AND 5 THEN 'Established Member (3-5 years)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 6 AND 10 THEN 'Long-term Member (6-10 years)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 11 AND 20 THEN 'Veteran Member (11-20 years)' WHEN date_diff('year', m.join_date, l.record_date) > 20 THEN 'Legacy Member (20+ years)' ELSE 'Unknown Tenure' END AS member_tenure_category, al.credit_score_code AS credit_score_code, CASE WHEN al.interest_rate <= 5.00 THEN 'Prime (≤5%)' WHEN al.interest_rate BETWEEN 5.01 AND 8.00 THEN 'Near-Prime (5-8%)' WHEN al.interest_rate BETWEEN 8.01 AND 12.00 THEN 'Standard (8-12%)' WHEN al.interest_rate BETWEEN 12.01 AND 18.00 THEN 'Subprime (12-18%)' WHEN al.interest_rate > 18.00 THEN 'High-Risk (>18%)' ELSE 'No Rate Data' END AS interest_rate_category, CASE WHEN ld.account_id IS NOT NULL THEN 1 ELSE 0 END AS has_loan_deferment, ld.start_date AS deferment_start_date, ld.end_deferment_date AS deferment_end_date, CASE WHEN ld.end_deferment_date IS NULL THEN 'Active (No End Date)' WHEN ld.end_deferment_date >= l.record_date THEN 'Active Deferment' WHEN ld.end_deferment_date < l.record_date AND ld.end_deferment_date >= date_add('month', -6, l.record_date) THEN 'Recently Completed (<6 months)' WHEN ld.end_deferment_date < date_add('month', -6, l.record_date) THEN 'Historical Deferment (>6 months ago)' ELSE NULL END AS deferment_status, CASE WHEN ld.end_deferment_date IS NULL AND ld.start_date IS NOT NULL THEN date_diff('day', ld.start_date, l.record_date) WHEN ld.end_deferment_date IS NOT NULL AND ld.start_date IS NOT NULL THEN date_diff('day', ld.start_date, ld.end_deferment_date) ELSE NULL END AS deferment_duration_days, COALESCE(sa.total_skip_payments_raw, 0) AS total_skip_payments, CASE WHEN COALESCE(sa.total_skip_payments_raw, 0) = 0 THEN NULL ELSE sa.total_skip_fees_raw END AS total_skip_fees, sa.last_skip_payment_date, COALESCE(sa.has_active_skip_payment, 0) AS has_active_skip_payment, COALESCE(sa.has_recent_skip_payment, 0) AS has_recent_skip_payment, sa.recent_skip_payment_date, CASE WHEN ld.account_id IS NOT NULL AND (ld.end_deferment_date IS NULL OR ld.end_deferment_date >= l.record_date) THEN 'DEFERRED (Active)' WHEN COALESCE(sa.has_active_skip_payment, 0) = 1 THEN 'SKIP PAYMENT (Active)' WHEN COALESCE(sa.has_recent_skip_payment, 0) = 1 THEN 'SKIP PAYMENT (Recent - Last 3 months)' WHEN ld.account_id IS NOT NULL AND ld.end_deferment_date < l.record_date AND ld.end_deferment_date >= date_add('month', -6, l.record_date) THEN 'DEFERRED (Recently Completed)' WHEN ld.account_id IS NOT NULL OR COALESCE(sa.total_skip_payments_raw, 0) > 0 THEN 'Has Deferment/Skip History' ELSE 'No Deferment/Skip' END AS deferment_skip_status, CASE WHEN (ld.account_id IS NOT NULL AND (ld.end_deferment_date IS NULL OR ld.end_deferment_date >= l.record_date)) OR COALESCE(sa.has_active_skip_payment, 0) = 1 OR COALESCE(sa.has_recent_skip_payment, 0) = 1 THEN 1 ELSE 0 END AS has_any_active_deferment FROM \"AwsDataCatalog\".\"silver_know\".\"eom_loan\" l JOIN \"AwsDataCatalog\".\"silver_know\".\"account\" a ON a.account_id = l.account_id AND a.credit_union = '{credit_union_q}' JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON al.account_id = a.account_id AND al.credit_union = '{credit_union_q}' JOIN \"AwsDataCatalog\".\"silver_know\".\"account_types\" t ON t.account_type = l.account_type AND t.credit_union = '{credit_union_q}' JOIN \"AwsDataCatalog\".\"silver_know\".\"member\" m ON a.member_number = m.member_number AND m.credit_union = '{credit_union_q}' JOIN \"AwsDataCatalog\".\"silver_know\".\"entity\" e ON m.member_entity_id = e.entity_id AND e.credit_union = '{credit_union_q}' LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"phone_number\" pn ON e.entity_id = pn.entity_id AND pn.credit_union = '{credit_union_q}' AND pn.primary_phone = 1 LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"loan_deferment\" ld ON l.account_id = ld.account_id AND ld.credit_union = '{credit_union_q}' AND ld.start_date <= l.record_date AND (ld.end_deferment_date IS NULL OR ld.end_deferment_date >= l.record_date) LEFT JOIN skip_agg sa ON sa.account_id = l.account_id AND sa.credit_union = l.credit_union AND sa.record_date = l.record_date WHERE l.credit_union = '{credit_union_q}' AND CAST(l.record_date AS date) >= date_add('month', -11, last_day_of_month(date_add('month', -1, current_date))) AND CAST(l.record_date AS date) <= last_day_of_month(date_add('month', -1, current_date)) AND CAST(l.record_date AS date) = last_day_of_month(CAST(l.record_date AS date)) AND l.date_closed IS NULL AND l.balance > 0 AND coalesce(a.current_balance, l.balance) > 0 AND coalesce(t.credit_card, 'N') NOT IN ('Y','X','1')), previous_month_data AS (SELECT md.loan_id, md.period, md.current_rank, md.bracket_delinquency, LAG(md.current_rank) OVER (PARTITION BY md.loan_id ORDER BY md.period) AS prev_rank, LAG(md.bracket_delinquency) OVER (PARTITION BY md.loan_id ORDER BY md.period) AS prev_bracket FROM monthly_data md) SELECT md.credit_union AS credit_union, fi.idfi AS idfi, ci.credit_union_name AS cu_name, md.id_general, md.period, md.date, md.loan_account_number, md.loan_id, md.date_loan_opened, md.loan_balance, md.loan_balance_pct_month, md.loan_balance_pct_delinquent, md.loan_main_category, md.loan_months_term, md.missed_first_payment_flag, md.first_payment_status, md.days_overdue_first_payment, md.last_payment_date, md.days_delinquency, md.bracket_delinquency, CASE WHEN pmd.prev_rank IS NULL THEN 'New Loan' WHEN md.current_rank > pmd.prev_rank THEN 'Deteriorated' WHEN md.current_rank = pmd.prev_rank THEN 'No Change' WHEN md.current_rank < pmd.prev_rank THEN 'Improved' ELSE 'Unknown' END AS status_loan_change, md.has_loan_deferment, md.deferment_start_date, md.deferment_end_date, md.deferment_status, md.deferment_duration_days, md.total_skip_payments, md.total_skip_fees, md.last_skip_payment_date, md.has_active_skip_payment, md.has_recent_skip_payment, md.recent_skip_payment_date, md.deferment_skip_status, md.has_any_active_deferment, md.credit_score, md.credit_score_code, md.interest_rate_category, md.next_payment_date, md.member_id, md.member_number, md.member_phone, md.member_email, md.member_gender, md.member_age_category, md.member_tenure_category FROM monthly_data md LEFT JOIN previous_month_data pmd ON md.loan_id = pmd.loan_id AND md.period = pmd.period LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(trim(fi.prodigy_code)) = '{credit_union_q}' LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"credit_union_info\" ci ON ci.credit_union = '{credit_union_q}' AND ci.flag_inactive <> 'Y' ORDER BY md.period DESC, md.loan_id) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"
    query_delinquency_last_month = f"UNLOAD (WITH l_month_end AS (SELECT l.credit_union, l.account_id, l.record_date FROM \"AwsDataCatalog\".\"silver_know\".\"eom_loan\" l WHERE l.credit_union = '{credit_union_q}' AND l.record_date >= date_add('month', -11, date_add('day', -1, date_trunc('month', current_date))) AND l.record_date <= date_add('day', -1, date_trunc('month', current_date)) AND l.record_date = date_add('day', -1, date_trunc('month', date_add('month', 1, l.record_date))) AND l.date_closed IS NULL AND l.balance > 0), skip_agg AS (SELECT lm.credit_union, lm.account_id, lm.record_date, SUM(CASE WHEN lsp.payment_to_skip <= lm.record_date THEN 1 ELSE 0 END) AS total_skip_payments_raw, SUM(CASE WHEN lsp.payment_to_skip <= lm.record_date THEN COALESCE(lsp.fee_amount, 0) ELSE 0 END) AS total_skip_fees_raw, MAX(CASE WHEN lsp.payment_to_skip <= lm.record_date THEN lsp.payment_to_skip END) AS last_skip_payment_date, MAX(CASE WHEN lsp.skip_completed = 0 AND lsp.payment_to_skip >= lm.record_date THEN 1 ELSE 0 END) AS has_active_skip_payment, MAX(CASE WHEN lsp.payment_to_skip >= date_add('month', -3, lm.record_date) AND lsp.payment_to_skip <= lm.record_date THEN 1 ELSE 0 END) AS has_recent_skip_payment, MAX(CASE WHEN lsp.payment_to_skip >= date_add('month', -3, lm.record_date) AND lsp.payment_to_skip <= lm.record_date THEN lsp.payment_to_skip END) AS recent_skip_payment_date FROM l_month_end lm LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"loan_skip_payment\" lsp ON lsp.account_id = lm.account_id AND lsp.credit_union = lm.credit_union GROUP BY lm.credit_union, lm.account_id, lm.record_date), monthly_data AS (SELECT a.credit_union, concat(date_format(l.record_date, '%Y-%m'), '-', cast(l.account_id AS varchar)) AS ID_General, date_format(l.record_date, '%Y-%m') AS Period, l.record_date AS Date, a.account_number AS Loan_Account_Number, l.account_id AS Loan_ID, a.date_opened AS Date_Loan_Opened, l.balance AS Loan_Balance, l.balance / SUM(l.balance) OVER (PARTITION BY date_format(l.record_date, '%Y-%m')) AS Loan_Balance_Pct_Month, CASE WHEN date_diff('day', l.next_payment_date, l.record_date) > 0 THEN l.balance / NULLIF(SUM(CASE WHEN date_diff('day', l.next_payment_date, l.record_date) > 0 THEN l.balance ELSE 0 END) OVER (PARTITION BY date_format(l.record_date, '%Y-%m')), 0) ELSE NULL END AS Loan_Balance_Pct_Delinquent, t.cb_loan_type, CASE WHEN t.cb_loan_type = '00' THEN 'Auto Loans' WHEN t.cb_loan_type = '01' THEN 'Unsecured/Personal Loans' WHEN t.cb_loan_type = '02' THEN 'Share/CD Secured Loans' WHEN t.cb_loan_type = '03' THEN 'Signature Secured Loans' WHEN t.cb_loan_type = '11' THEN 'Recreational Vehicle Loans' WHEN t.cb_loan_type = '15' THEN 'Overdraft Protection' WHEN t.cb_loan_type = '18' THEN 'Credit Card' WHEN t.cb_loan_type = '26' THEN 'Real Estate/Mortgage Loans' WHEN t.cb_loan_type = '89' THEN 'Home Equity Loans' ELSE 'Unclassified' END AS Loan_Main_Category, al.number_of_payments AS Loan_Months_Term, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 1 ELSE 0 END AS Missed_First_Payment_Flag, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 'Missed First Payment (Overdue)' WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) = 0 THEN 'Due Today (Not Paid Yet)' WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) < 0 THEN 'No Payment Yet (Not Due)' WHEN al.last_payment_date IS NOT NULL THEN 'Has Made Payment(s)' ELSE 'Unknown' END AS First_Payment_Status, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN date_diff('day', l.next_payment_date, l.record_date) ELSE NULL END AS Days_Overdue_First_Payment, al.last_payment_date AS Last_Payment_Date, CASE WHEN date_diff('day', l.next_payment_date, l.record_date) < 0 THEN 0 ELSE date_diff('day', l.next_payment_date, l.record_date) END AS Days_Delinquency, CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 'First Payment Delinquency' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 1 AND 30 THEN '1-30 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 31 AND 60 THEN '31-60 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 61 AND 90 THEN '61-90 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 91 AND 120 THEN '91-120 days' WHEN date_diff('day', l.next_payment_date, l.record_date) > 120 THEN 'Over 120 days' ELSE '0 days' END AS Bracket_Delinquency, (coalesce(array_position(ARRAY['0 days','First Payment Delinquency','1-30 days','31-60 days','61-90 days','91-120 days','Over 120 days'], CASE WHEN al.last_payment_date IS NULL AND l.next_payment_date IS NOT NULL AND date_diff('day', l.next_payment_date, l.record_date) >= 1 THEN 'First Payment Delinquency' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 1 AND 30 THEN '1-30 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 31 AND 60 THEN '31-60 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 61 AND 90 THEN '61-90 days' WHEN date_diff('day', l.next_payment_date, l.record_date) BETWEEN 91 AND 120 THEN '91-120 days' WHEN date_diff('day', l.next_payment_date, l.record_date) > 120 THEN 'Over 120 days' ELSE '0 days' END), 0) - 1) AS current_rank, al.credit_score AS Credit_Score, l.next_payment_date AS Next_Payment_Date, m.member_entity_id AS Member_ID, a.member_number AS Member_Number, pn.phone_number AS Member_Phone, e.email1 AS Member_Email, CASE WHEN e.gender = 'M' THEN 'Male' WHEN e.gender = 'F' THEN 'Female' WHEN e.gender = 'O' THEN 'Other' WHEN e.gender = '' OR e.gender IS NULL THEN 'Unknown' ELSE 'Other' END AS Member_Gender, CASE WHEN e.dob IS NULL THEN 'Age Unknown' WHEN date_diff('year', e.dob, l.record_date) < 25 THEN 'Under 25' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 25 AND 34 THEN '25-34 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 35 AND 44 THEN '35-44 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 45 AND 54 THEN '45-54 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 55 AND 64 THEN '55-64 years' WHEN date_diff('year', e.dob, l.record_date) BETWEEN 65 AND 74 THEN '65-74 years' WHEN date_diff('year', e.dob, l.record_date) >= 75 THEN '75+ years' ELSE 'Age Unknown' END AS Member_Age_Category, CASE WHEN m.join_date IS NULL THEN 'Unknown Tenure' WHEN date_diff('year', m.join_date, l.record_date) < 1 THEN 'New Member (<1 year)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 1 AND 2 THEN 'Recent Member (1-2 years)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 3 AND 5 THEN 'Established Member (3-5 years)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 6 AND 10 THEN 'Long-term Member (6-10 years)' WHEN date_diff('year', m.join_date, l.record_date) BETWEEN 11 AND 20 THEN 'Veteran Member (11-20 years)' WHEN date_diff('year', m.join_date, l.record_date) > 20 THEN 'Legacy Member (20+ years)' ELSE 'Unknown Tenure' END AS Member_Tenure_Category, al.credit_score_code AS Credit_Score_Code, CASE WHEN al.interest_rate <= 5.00 THEN 'Prime (≤5%)' WHEN al.interest_rate BETWEEN 5.01 AND 8.00 THEN 'Near-Prime (5-8%)' WHEN al.interest_rate BETWEEN 8.01 AND 12.00 THEN 'Standard (8-12%)' WHEN al.interest_rate BETWEEN 12.01 AND 18.00 THEN 'Subprime (12-18%)' WHEN al.interest_rate > 18.00 THEN 'High-Risk (>18%)' ELSE 'No Rate Data' END AS Interest_Rate_Category, CASE WHEN ld.account_id IS NOT NULL THEN 1 ELSE 0 END AS Has_Loan_Deferment, ld.start_date AS Deferment_Start_Date, ld.end_deferment_date AS Deferment_End_Date, CASE WHEN ld.end_deferment_date IS NULL THEN 'Active (No End Date)' WHEN ld.end_deferment_date >= l.record_date THEN 'Active Deferment' WHEN ld.end_deferment_date < l.record_date AND ld.end_deferment_date >= date_add('month', -6, l.record_date) THEN 'Recently Completed (<6 months)' WHEN ld.end_deferment_date < date_add('month', -6, l.record_date) THEN 'Historical Deferment (>6 months ago)' ELSE NULL END AS Deferment_Status, CASE WHEN ld.end_deferment_date IS NULL AND ld.start_date IS NOT NULL THEN date_diff('day', ld.start_date, l.record_date) WHEN ld.end_deferment_date IS NOT NULL AND ld.start_date IS NOT NULL THEN date_diff('day', ld.start_date, ld.end_deferment_date) ELSE NULL END AS Deferment_Duration_Days, COALESCE(sa.total_skip_payments_raw, 0) AS Total_Skip_Payments, CASE WHEN COALESCE(sa.total_skip_payments_raw, 0) = 0 THEN NULL ELSE sa.total_skip_fees_raw END AS Total_Skip_Fees, sa.last_skip_payment_date AS Last_Skip_Payment_Date, COALESCE(sa.has_active_skip_payment, 0) AS Has_Active_Skip_Payment, COALESCE(sa.has_recent_skip_payment, 0) AS Has_Recent_Skip_Payment, sa.recent_skip_payment_date AS Recent_Skip_Payment_Date, CASE WHEN ld.account_id IS NOT NULL AND (ld.end_deferment_date IS NULL OR ld.end_deferment_date >= l.record_date) THEN 'DEFERRED (Active)' WHEN COALESCE(sa.has_active_skip_payment, 0) = 1 THEN 'SKIP PAYMENT (Active)' WHEN COALESCE(sa.has_recent_skip_payment, 0) = 1 THEN 'SKIP PAYMENT (Recent - Last 3 months)' WHEN ld.account_id IS NOT NULL AND ld.end_deferment_date < l.record_date AND ld.end_deferment_date >= date_add('month', -6, l.record_date) THEN 'DEFERRED (Recently Completed)' WHEN ld.account_id IS NOT NULL OR COALESCE(sa.total_skip_payments_raw, 0) > 0 THEN 'Has Deferment/Skip History' ELSE 'No Deferment/Skip' END AS Deferment_Skip_Status, CASE WHEN (ld.account_id IS NOT NULL AND (ld.end_deferment_date IS NULL OR ld.end_deferment_date >= l.record_date)) OR COALESCE(sa.has_active_skip_payment, 0) = 1 OR COALESCE(sa.has_recent_skip_payment, 0) = 1 THEN 1 ELSE 0 END AS Has_Any_Active_Deferment FROM \"AwsDataCatalog\".\"silver_know\".\"eom_loan\" l JOIN \"AwsDataCatalog\".\"silver_know\".\"account\" a ON a.account_id = l.account_id AND a.credit_union = l.credit_union JOIN \"AwsDataCatalog\".\"silver_know\".\"account_loan\" al ON al.account_id = a.account_id AND al.credit_union = a.credit_union JOIN \"AwsDataCatalog\".\"silver_know\".\"account_types\" t ON t.account_type = l.account_type AND t.credit_union = l.credit_union JOIN \"AwsDataCatalog\".\"silver_know\".\"member\" m ON a.member_number = m.member_number AND a.credit_union = m.credit_union JOIN \"AwsDataCatalog\".\"silver_know\".\"entity\" e ON m.member_entity_id = e.entity_id AND m.credit_union = e.credit_union LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"phone_number\" pn ON e.entity_id = pn.entity_id AND e.credit_union = pn.credit_union AND pn.primary_phone = 1 LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"loan_deferment\" ld ON l.account_id = ld.account_id AND l.credit_union = ld.credit_union AND ld.start_date <= l.record_date AND (ld.end_deferment_date IS NULL OR ld.end_deferment_date >= l.record_date) LEFT JOIN skip_agg sa ON sa.account_id = l.account_id AND sa.credit_union = l.credit_union AND sa.record_date = l.record_date WHERE l.credit_union = '{credit_union_q}' AND l.record_date >= date_add('month', -11, date_add('day', -1, date_trunc('month', current_date))) AND l.record_date <= date_add('day', -1, date_trunc('month', current_date)) AND l.record_date = date_add('day', -1, date_trunc('month', date_add('month', 1, l.record_date))) AND l.date_closed IS NULL AND l.balance > 0 AND coalesce(a.current_balance, l.balance) > 0 AND coalesce(t.credit_card, 'N') NOT IN ('Y','X','1') ), previous_month_data AS (SELECT md.Loan_ID, md.Period, md.current_rank, md.Bracket_Delinquency, LAG(md.current_rank) OVER (PARTITION BY md.Loan_ID ORDER BY md.Period) AS prev_rank, LAG(md.Bracket_Delinquency) OVER (PARTITION BY md.Loan_ID ORDER BY md.Period) AS prev_bracket FROM monthly_data md) SELECT md.credit_union AS credit_union, fi.idfi AS idFi, ci.credit_union_name AS CU_Name, md.ID_General, md.Period, md.Date, md.Loan_Account_Number, md.Loan_ID, md.Date_Loan_Opened, md.Loan_Balance, md.Loan_Balance_Pct_Month, md.Loan_Balance_Pct_Delinquent, md.Loan_Main_Category, md.Loan_Months_Term, md.Missed_First_Payment_Flag, md.First_Payment_Status, md.Days_Overdue_First_Payment, md.Last_Payment_Date, md.Days_Delinquency, md.Bracket_Delinquency, CASE WHEN pmd.prev_rank IS NULL THEN 'New Loan' WHEN md.current_rank > pmd.prev_rank THEN 'Deteriorated' WHEN md.current_rank = pmd.prev_rank THEN 'No Change' WHEN md.current_rank < pmd.prev_rank THEN 'Improved' ELSE 'Unknown' END AS Status_Loan_Change, md.Has_Loan_Deferment, md.Deferment_Start_Date, md.Deferment_End_Date, md.Deferment_Status, md.Deferment_Duration_Days, md.Total_Skip_Payments, md.Total_Skip_Fees, md.Last_Skip_Payment_Date, md.Has_Active_Skip_Payment, md.Has_Recent_Skip_Payment, md.Recent_Skip_Payment_Date, md.Deferment_Skip_Status, md.Has_Any_Active_Deferment, md.Credit_Score, md.Credit_Score_Code, md.Interest_Rate_Category, md.Next_Payment_Date, md.Member_ID, md.Member_Number, md.Member_Phone, md.Member_Email, md.Member_Gender, md.Member_Age_Category, md.Member_Tenure_Category FROM monthly_data md LEFT JOIN previous_month_data pmd ON md.Loan_ID = pmd.Loan_ID AND md.Period = pmd.Period LEFT JOIN \"AwsDataCatalog\".\"blossom_prod_info\".\"blossomcompany_olb_map\" fi ON lower(trim(fi.prodigy_code)) = lower(trim(md.credit_union)) LEFT JOIN \"AwsDataCatalog\".\"silver_know\".\"credit_union_info\" ci ON ci.credit_union = md.credit_union AND ci.flag_inactive <> 'Y' ORDER BY md.Period DESC, md.Loan_ID) TO '{temp_path}' WITH (format = 'PARQUET', compression = 'SNAPPY');"

    queries_by_name = { "accounts_general": query_accounts_general, 
                       "accounts_transactions": query_accounts_transactions, 
                       "cards_general": query_cards_general, 
                       "cards_transactions": query_cards_transactions, 
                       "gl_accounts_general": query_gl_accounts_general, 
                       "gl_accounts_transactions": query_gl_accounts_transactions, 
                       "gl_certs": query_gl_certs, 
                       "gl_dividends": query_gl_dividends, 
                       "gl_loans": query_gl_loans, 
                       "loans_applications": query_loans_applications, 
                       "loans_general": query_loans_general, 
                       "member_details": query_member_details, 
                       "member_key_trends": query_member_key_trends, 
                       "member_profile": query_member_profile, 
                       "member_transactions": query_member_transactions, 
                       "products_overview": query_products_overview,
                       "delinquency_history": query_delinquency_history,
                       "delinquency_last_month": query_delinquency_last_month}


    return queries_by_name[query_name]
